/* MODULE tn03 · Bước 6 Thử nghiệm · Thử sáng tạo: creative testing
   10 bài × 7 câu. Bàn về CÁCH THỬ creative (không dạy viết ý tưởng). Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tn03', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tn03-01', skill:'creative', read:'6 phút', t:'Có nên quay TVC 300 triệu khi chưa biết ý tưởng nào chạy?',
  situation:'Một thương hiệu nước mắm đóng chai ở Phú Quốc có ba ý tưởng cho chiến dịch Tết: "bữa cơm đoàn viên", "mẹ chọn nước mắm cho con", "vị biển thật". Agency báo giá quay một TVC hoàn chỉnh 300 triệu đồng. Giám đốc muốn chọn ngay ý tưởng mình thích nhất để kịp lịch lên sóng sau sáu tuần.',
  concept:{ name:'Thử concept trước khi sản xuất lớn',
    body:'Một <b>concept test</b> đưa ý tưởng ra trước khách thật ở dạng rẻ: ảnh tĩnh, video dựng từ ảnh có sẵn, một câu tiêu đề kèm hình minh hoạ. Mục tiêu không phải đo doanh số mà loại sớm những ý tưởng không khiến người ta dừng lại hay bấm vào; chi phí thường chỉ vài phần trăm chi phí sản xuất. Hai giới hạn cần nhớ. Một: chênh lệch phải vượt dao động may rủi (quy tắc ±2×√tổng ở bài "40 đơn so với 30 đơn") mới đáng tin. Hai: CTR đo sự chú ý trong vài giây, không đo sức xây thương hiệu; ý tưởng cảm xúc chậm có thể thua CTR mà vẫn đáng giữ (xem bài 07).' },
  example:'Nhóm dựng ba video 15 giây từ ảnh và chữ, mỗi bản chi 3 triệu quảng cáo Facebook cho cùng tệp khách nữ 28–45 tuổi, khoảng 40.000 hiển thị mỗi bản (số minh hoạ). Sau năm ngày: "mẹ chọn cho con" 720 lượt bấm (CTR 1,8%), "đoàn viên" 440 (1,1%), "vị biển thật" 280 (0,7%). Chênh 280 lượt giữa hai bản đầu gấp hơn 4 lần dao động may rủi (khoảng ±68), nên đủ để xếp hạng. Tổng chi thử 9 triệu, tức 3% ngân sách quay. Đội quay "mẹ chọn cho con" và giữ "đoàn viên" làm dự phòng, vì CTR thấp chưa chắc là thiếu sức xây cảm xúc.',
  takeaway:'Tiền sản xuất đặt vào ý tưởng đã qua một vòng thử rẻ, không đặt vào ý tưởng được thích nhất trong phòng họp.',
  apply:'Chọn một chiến dịch sắp tới của bạn. Nói trong 60 giây: bạn sẽ dựng bản thử rẻ nhất nào cho mỗi ý tưởng, và chỉ số nào quyết định ý tưởng được quay.',
  mistakes:['Coi bản thử thô là "làm ẩu", nên đầu tư sản xuất đẹp ngay cho mọi ý tưởng.','Đọc kết quả concept test như dự báo doanh số chính xác của bản hoàn chỉnh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ba video dựng thô, mỗi bản chi 3 triệu, có đủ để chọn ý tưởng quay TVC không?',
    options:[{k:'a',t:'Không, vì video thô sẽ bị khách chê và làm hỏng hình ảnh thương hiệu'},{k:'b',t:'Đủ để loại ý tưởng yếu rõ rệt, dù chưa dự báo chính xác kết quả cuối'},
             {k:'c',t:'Đủ để biết chính xác doanh số Tết của từng ý tưởng khi lên TVC'},{k:'d',t:'Không, vì phải thử bằng bản quay hoàn chỉnh thì số liệu mới có giá trị'}],
    answer:'b', why:{a:'Chạy ngắn ngày cho một tệp nhỏ, rủi ro hình ảnh thấp; cái được là biết ý tưởng nào khiến người ta dừng lại.',
      b:'Đúng. Concept test là bộ lọc: khoảng cách lớn giữa các ý tưởng đủ để loại bớt, không phải để dự báo doanh số.',
      c:'Bản thô và TVC khác nhau về chất lượng, kênh và thời điểm; con số chỉ mang tính định hướng.',
      d:'Nếu phải quay xong mới thử thì đã tiêu hết tiền; ý nghĩa của thử concept là thử trước khi tốn.'} },
  { type:'mcq', stem:'Giám đốc vẫn muốn quay ngay ý tưởng "vị biển thật" vì ông thích nhất. Bạn làm gì?',
    options:[{k:'a',t:'Làm theo, vì người quyết cuối là giám đốc và ông hiểu thương hiệu nhất'},{k:'b',t:'Quay cả ba TVC cho chắc, rồi chọn bản đẹp nhất để lên sóng dịp Tết'},
             {k:'c',t:'Đề xuất 5 ngày và 9 triệu để thử ba bản thô, rồi quyết dựa trên số liệu'},{k:'d',t:'Hỏi ý kiến cả phòng marketing rồi bỏ phiếu chọn ý tưởng được thích nhất'}],
    answer:'c', why:{a:'Sở thích của một người không thay thế được phản ứng của khách; chỉ cần vài ngày là có bằng chứng.',
      b:'Quay ba TVC tốn gấp ba mà vẫn phải chọn; thử bản rẻ giải quyết cùng câu hỏi với 3% chi phí.',
      c:'Đúng. Chi phí và thời gian nhỏ, vừa với lịch sáu tuần, và biến tranh luận thành dữ liệu.',
      d:'Bỏ phiếu nội bộ vẫn là ý kiến người trong nhà, không phải hành vi của khách hàng mục tiêu.'} },
  { type:'calc', stem:'Mỗi bản có khoảng 40.000 hiển thị. "Đoàn viên" được 440 lượt bấm, "vị biển thật" 280. Theo quy tắc ±2×√(kA + kB), khoảng dao động may rủi của chênh lệch giữa hai bản là bao nhiêu lượt bấm (làm tròn 1 chữ số thập phân)?',
    unit:'lượt bấm', ans:53.7, tol:0.3, wrong:[[26.8,'SAI_TINH_TOAN'],[160,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN'],
    steps:['Tổng số lượt bấm = 440 + 280 = 720.','√720 ≈ 26,8; nhân 2 ra ≈ <b>53,7 lượt</b>.','Chênh thực tế 160 lượt gấp gần 3 lần mức này, nên "đoàn viên" hơn "vị biển thật" là đáng tin.'] },
  { type:'mcq', stem:'Hai ý tưởng X và Y cùng 40.000 hiển thị: X 410 lượt bấm, Y 360 (CTR 1,03% và 0,9%). Dao động may rủi của chênh lệch khoảng ±55 lượt. Bạn quyết định thế nào?',
    options:[{k:'a',t:'Quay X, vì CTR cao hơn 14% nên đã đủ để xếp X trên Y'},{k:'b',t:'Chưa phân biệt được: chạy thêm hoặc chọn theo tiêu chí ngoài CTR'},
             {k:'c',t:'Loại cả hai vì CTR quanh 1%, thấp hơn mức chuẩn 2% của ngành'},{k:'d',t:'Quay cả hai bản rồi chạy thật để xem bản nào thắng'}],
    answer:'b', why:{a:'Hơn 14% nghe lớn nhưng nền chỉ vài trăm lượt; chênh 50 lượt nhỏ hơn dao động ±55 nên có thể chỉ là may rủi.',
      b:'Đúng. Chênh lệch chưa vượt dao động: chạy thêm hiển thị, hoặc dùng tiêu chí khác như chi phí sản xuất và độ khớp thương hiệu.',
      c:'Không có mốc 2% chung cho mọi ngành; điều cần đọc là khoảng cách tương đối giữa các ý tưởng.',
      d:'Quay cả hai là tiêu tiền lớn để trả lời câu hỏi mà vài ngày chạy thêm giải quyết rẻ hơn nhiều.'} },
  { type:'mcq', stem:'Vì sao ba bản thử phải chạy cùng tệp khách, cùng ngân sách và cùng khoảng thời gian?',
    options:[{k:'a',t:'Để chênh lệch kết quả đến từ ý tưởng, không phải từ điều kiện chạy khác nhau'},{k:'b',t:'Để nền tảng quảng cáo tính giá rẻ hơn khi các nhóm quảng cáo giống nhau'},
             {k:'c',t:'Để tiết kiệm công thiết lập, còn kết quả thì không bị ảnh hưởng gì'},{k:'d',t:'Để báo cáo trông gọn và dễ trình bày trước ban giám đốc hơn'}],
    answer:'a', why:{a:'Đúng. Giữ mọi thứ khác như nhau thì mới quy được khác biệt cho ý tưởng.',
      b:'Giá đấu thầu không giảm vì các nhóm giống nhau; lý do là so sánh công bằng.',
      c:'Tệp khách và thời điểm khác nhau có thể tạo chênh lệch lớn hơn cả chênh lệch giữa ý tưởng.',
      d:'Trình bày gọn là phụ; điều cốt lõi là loại bỏ biến gây nhiễu.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa muốn thử hai concept mùa hè nhưng chỉ có 2 triệu đồng. Cách thử rẻ và hợp lý nhất là gì?',
    options:[{k:'a',t:'Thuê KOL quay hai video chuyên nghiệp rồi so lượt thích sau khi đăng'},{k:'b',t:'Đợi đến khi có đủ ngân sách để quay bản đẹp rồi mới thử cho chuẩn xác'},
             {k:'c',t:'Hai ảnh tĩnh kèm tiêu đề, chạy ngang nhau cho cùng tệp khách vài ngày'},{k:'d',t:'Đăng cả hai lên trang cá nhân của nhân viên và đếm số bình luận khen'}],
    answer:'c', why:{a:'Thuê KOL vượt xa 2 triệu và trộn thêm biến là sức hút của người nổi tiếng.',
      b:'Chờ ngân sách lớn là đi ngược mục đích: thử rẻ để khỏi phí tiền lớn.',
      c:'Đúng. Ảnh tĩnh và tiêu đề đủ để đo sự chú ý, chi phí vừa túi.',
      d:'Bạn bè của nhân viên không phải khách mục tiêu, và lời khen xã giao không phải hành vi.'} },
  { type:'mcq', stem:'Concept A thắng rõ ở bản thô. Sau khi quay TVC, bản hoàn chỉnh lại có CTR thấp hơn bản thô. Giải thích nào hợp lý nhất?',
    options:[{k:'a',t:'Concept test đã sai, lẽ ra nên chọn theo cảm nhận giám đốc'},{k:'b',t:'TVC thường kém bản thô vì khách ghét quảng cáo làm quá đẹp'},
             {k:'c',t:'Do đổi kênh chạy nên chỉ số CTR không còn ý nghĩa gì với chiến dịch'},{k:'d',t:'Khâu sản xuất có thể đã làm mờ đi điều khiến bản thô hấp dẫn'}],
    answer:'d', why:{a:'Một kết quả lệch không phủ nhận việc thử; nó chỉ ra cần kiểm tra khâu chuyển từ ý tưởng sang thành phẩm.',
      b:'Không có quy luật như vậy; nhiều TVC chạy tốt hơn bản thô.',
      c:'Đổi kênh có ảnh hưởng, nhưng vẫn cần đọc lý do, không vứt bỏ chỉ số.',
      d:'Đúng. Hãy so hai bản: câu mở, hình chính, thông điệp có còn giữ như bản đã thắng không.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tn03-02', skill:'creative', read:'7 phút', t:'Ba giây đầu video giữ hay đánh rơi người xem?',
  situation:'Một thương hiệu kem chống nắng nội địa chạy video 30 giây trên TikTok. Mở đầu là logo xoay trong 3 giây, sau đó cô gái mới xuất hiện dưới nắng. Báo cáo cho thấy 10.000 lượt hiển thị nhưng chỉ 1.800 người xem quá 3 giây. Đội muốn biết có nên quay lại cả video không.',
  concept:{ name:'Thử hook — ba giây đầu',
    body:'Trên mạng xã hội, người xem quyết định lướt hay dừng trong vài giây đầu. Phần mở đầu đó gọi là <b>hook</b>. Cách thử rẻ nhất là giữ nguyên thân video và chỉ thay 3 giây đầu: một bản mở bằng câu hỏi, một bản mở bằng cảnh "trước – sau", một bản mở bằng khoảnh khắc lạ. Vì thân video giống nhau, chênh lệch về tỉ lệ xem quá 3 giây gần như chỉ do hook. Thử hook thường cho khác biệt lớn với chi phí dựng rất nhỏ.' },
  example:'Đội giữ 27 giây sau, dựng lại ba đầu mới: (1) "Bôi kem mà vẫn cháy nắng?" kèm cận mặt, (2) hai nửa mặt sau một ngày đi biển, (3) cô gái đổ kem lên tay dưới nắng gắt. Mỗi bản 10.000 hiển thị. Tỉ lệ xem quá 3 giây: bản cũ 18%, (1) 31%, (2) 38%, (3) 24%. Chỉ dựng lại 3 giây mà số người ở lại gấp hơn hai lần.',
  takeaway:'Trước khi quay lại cả video, hãy thay riêng ba giây đầu — phần rẻ nhất để sửa và đắt nhất nếu bỏ qua.',
  points:["Người xem lướt theo phản xạ, nên vài giây đầu họ chưa quyết định. Hook tốt đưa ra lý do ở lại, như câu hỏi hay hình lạ, trước khi ngón tay kịp vuốt.","Giữ nguyên 27 giây sau để biến số duy nhất là phần mở đầu. Mỗi bản hook cần số hiển thị ngang nhau, cùng khung giờ và cùng tệp người xem.","Hook phải khớp với thân video: nó hứa một điều và phần sau trả lời đúng điều đó. Hook lạc đề giữ người xem 3 giây rồi mất họ ngay sau đó."],
  counter:"Giả sử cũng video kem chống nắng, nhưng chạy cho nhóm đang tìm kem đi biển. Nhóm này đã có sẵn ý định, nên hook mới chỉ đẩy tỉ lệ xem lên chút ít, còn điểm nghẽn nằm ở thân video hoặc lời kêu gọi. Dấu hiệu nhận ra: các bản hook chênh nhau nhỏ, tỉ lệ xem hết vẫn thấp. Lúc đó hãy sửa phần giữa và cuối.",
  deeper:"Người làm nghề coi hook là đòn bẩy rẻ, nhưng không phải đòn bẩy duy nhất. Đánh đổi chính: hook giật gân kéo được nhiều người dừng lại mà có thể kéo sai người, làm tỉ lệ bấm mua thấp. Tín hiệu cần theo dõi ngoài tỉ lệ xem quá 3 giây là tỉ lệ xem hết và CTR của từng bản hook. Khái niệm kề cận là đọc chỉ số theo tầng: hook sửa tầng đầu, thân video sửa tầng giữa. Phép kiểm tra trong tuần: lấy một video đang chạy, dựng ba bản hook khác nhau, mỗi bản 10.000 hiển thị, rồi xếp hạng theo cả tỉ lệ xem lẫn CTR.",
  apply:'Mở một video quảng cáo của bạn. Nói trong 60 giây: ba giây đầu đang cho người xem thấy gì, và bạn sẽ thử hai hook thay thế nào.',
  mistakes:['Mở video bằng logo hoặc lời chào dài vì nghĩ phải "giới thiệu thương hiệu" trước.','Thay cả hook lẫn thân video cùng lúc, rồi không biết phần nào tạo khác biệt.'],
  q:[
  { type:'mcq', stem:'Đoán trước: chỉ thay 3 giây đầu và giữ nguyên 27 giây sau thì tỉ lệ xem quá 3 giây thay đổi đến đâu?',
    options:[{k:'a',t:'Gần như không đổi, vì người xem quyết định dựa trên cả 30 giây video'},{k:'b',t:'Chỉ đổi vài phần nghìn, vì thuật toán mới là bên quyết định lượt xem'},
             {k:'c',t:'Có thể đổi rất lớn, vì đó chính là lúc người xem quyết định dừng hay lướt'},{k:'d',t:'Giảm, vì người xem sẽ thấy mở đầu không khớp với phần còn lại'}],
    answer:'c', why:{a:'Người xem chưa thấy phần sau khi đã lướt đi; quyết định nằm ở mấy giây đầu.',
      b:'Thuật toán phân phối lượt hiển thị, nhưng người xem mới quyết định ở lại hay không.',
      c:'Đúng. Hook là cửa vào; thay hook có thể nhân đôi số người ở lại.',
      d:'Nếu hook mới cùng chủ đề thì không lệch; rủi ro này kiểm soát được khi dựng.'} },
  { type:'mcq', stem:'Bạn có ngân sách dựng lại một lần. Bạn chọn làm gì với video kem chống nắng?',
    options:[{k:'a',t:'Dựng 3 bản hook mới, giữ nguyên thân video, chạy ngang nhau để chọn'},{k:'b',t:'Quay lại cả video với người mẫu nổi tiếng hơn để tăng sức hút'},
             {k:'c',t:'Kéo logo dài thêm để khách nhớ thương hiệu kỹ hơn ngay từ đầu'},{k:'d',t:'Rút video còn 15 giây, giữ logo mở đầu nhưng cắt bớt phần thân'}],
    answer:'a', why:{a:'Đúng. Chỉ đổi một biến là hook, chi phí thấp, đọc được ngay phần nào có tác dụng.',
      b:'Quay lại cả video tốn kém và thay nhiều biến cùng lúc; vấn đề đang nằm ở 3 giây đầu.',
      c:'Logo mở đầu chính là nghi phạm làm người xem lướt đi; kéo dài càng tệ.',
      d:'Rút ngắn không sửa được chỗ người xem bỏ đi ngay từ giây đầu.'} },
  { type:'calc', stem:'Hook mới có 10.000 lượt hiển thị, 3.800 người xem quá 3 giây. Tỉ lệ xem quá 3 giây là bao nhiêu phần trăm?',
    unit:'%', ans:38, tol:0.1, wrong:[[263.2,'SAI_MAU_SO'],[3.8,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tỉ lệ xem quá 3 giây = người xem quá 3 giây ÷ lượt hiển thị.','3.800 ÷ 10.000 = 0,38 = <b>38%</b>.'] },
  { type:'mcq', stem:'Hook "trước – sau" tăng tỉ lệ xem 3 giây từ 18% lên 38%. Tăng bao nhiêu và nên nói thế nào?',
    options:[{k:'a',t:'Tăng 20%, vì 38 trừ 18 bằng 20 nên có thể báo cáo tăng 20%'},{k:'b',t:'Tăng 20 điểm phần trăm, tức gấp khoảng 2,1 lần mức cũ'},
             {k:'c',t:'Tăng 211%, vì chia 38 cho 18 rồi nhân với 100 là ra con số tăng'},{k:'d',t:'Tăng 38%, vì đó là con số mới đạt được sau khi thay hook'}],
    answer:'b', why:{a:'Hiệu hai tỉ lệ là điểm phần trăm, không phải phần trăm tăng.',
      b:'Đúng. 38 − 18 = 20 điểm; 38 ÷ 18 ≈ 2,1 lần, tức tăng khoảng 111%.',
      c:'38 ÷ 18 ≈ 2,11 là tỉ số; mức tăng là 111%, không phải 211%.',
      d:'38% là mức mới, không phải mức tăng.'} },
  { type:'mcq', stem:'Hook (1) "Bôi kem mà vẫn cháy nắng?" giữ người xem tốt nhưng rất ít người bấm mua. Điều gì có thể đang xảy ra?',
    options:[{k:'a',t:'Hook tạo tò mò nhưng thân video không trả lời được câu hỏi hook đặt ra'},{k:'b',t:'Tỉ lệ xem cao rồi sẽ bán được, cứ chờ thêm vài ngày cho đơn về'},
             {k:'c',t:'Giá sản phẩm quá cao nên không liên quan gì đến creative'},{k:'d',t:'TikTok không phải kênh bán hàng nên không ai bấm mua'}],
    answer:'a', why:{a:'Đúng. Hook hứa một điều; nếu phần sau không giải quyết, người xem ở lại rồi rời đi tay trắng.',
      b:'Giữ chân không tự động thành mua; cần xem cả chỉ số ở cuối phễu.',
      c:'Giá có thể là một lý do, nhưng các hook khác cùng giá vẫn bán được thì creative vẫn đáng nghi.',
      d:'Nhiều thương hiệu bán tốt trên TikTok; kết luận này quá rộng.'} },
  { type:'mcq', stem:'Một quán phở muốn thử hook cho video 20 giây. Bản nào là thử hook đúng nghĩa?',
    options:[{k:'a',t:'Hai video khác hẳn nhau, một quay bếp và một quay khách ăn'},{k:'b',t:'Cùng video, một bản đăng buổi sáng, một bản đăng buổi tối'},
             {k:'c',t:'Cùng video, một bản có nhạc sôi động, một bản có nhạc nhẹ suốt 20 giây'},{k:'d',t:'Cùng 17 giây sau, đổi 3 giây đầu: cận nồi nước dùng vs cảnh chan nước'}],
    answer:'d', why:{a:'Hai video khác hẳn thì thay đổi mọi thứ, không cô lập được hook.',
      b:'Đó là thử giờ đăng, không phải thử hook.',
      c:'Đổi nhạc suốt video là thử âm thanh, không phải ba giây mở đầu.',
      d:'Đúng. Chỉ phần mở đầu khác nhau, phần còn lại giữ nguyên.'} },
  { type:'mcq', stem:'Vì sao mở đầu bằng logo xoay 3 giây thường làm tỉ lệ xem giảm trên mạng xã hội?',
    options:[{k:'a',t:'Vì nền tảng phạt những video có logo ở ngay giây đầu tiên'},{k:'b',t:'Vì logo chưa nói gì liên quan đến người xem nên họ không có lý do dừng lại'},
             {k:'c',t:'Vì logo nhỏ quá nên người xem nhìn không rõ trên màn hình điện thoại'},{k:'d',t:'Vì khán giả trẻ ghét thương hiệu và chủ động né dấu hiệu quảng cáo'}],
    answer:'b', why:{a:'Không có quy định phạt như vậy; vấn đề là hành vi người xem.',
      b:'Đúng. Người xem dừng vì điều liên quan đến họ, logo chưa cho họ lý do đó.',
      c:'Dù logo to rõ thì người xem vẫn lướt nếu không thấy gì đáng xem.',
      d:'Khái quát quá mức; người trẻ vẫn xem quảng cáo nếu nó đáng xem.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tn03-03', skill:'creative', read:'6 phút', t:'Đổi tiêu đề hay đổi ảnh chính trước?',
  situation:'Một shop giày thể thao trên Shopee có tỉ lệ bấm vào sản phẩm thấp. Ảnh chính hiện là đôi giày chụp nền trắng, tiêu đề dài khoảng 120 ký tự (ví dụ minh hoạ) nhồi từ khoá. Chủ shop có một buổi chiều và muốn biết nên thử đổi thứ gì trước để thấy khác biệt nhanh nhất.',
  concept:{ name:'Thử yếu tố chính theo thứ tự tác động',
    body:'Trên sàn hay trang tìm kiếm, mắt người mua thường dừng ở ảnh <b>trước</b> rồi mới lướt tiêu đề (cách hiểu phổ biến, chưa phải quy luật; hãy tự kiểm bằng thử nghiệm của shop). Vì vậy ảnh chính là <b>giả thuyết nên thử đầu tiên</b> khi vấn đề là tỉ lệ bấm thấp. Nhưng tiêu đề có việc khác: quyết định bạn có hiện ra khi khách gõ từ khoá hay không. Nếu lượt hiển thị đã thấp, hãy thử tiêu đề trước. Nguyên tắc: mỗi lần đổi một yếu tố, và so hai bản chạy cùng lúc. Đổi cả ảnh lẫn tiêu đề một lượt thì dù tốt lên, bạn cũng không biết nhờ cái nào để áp dụng cho sản phẩm khác.' },
  example:'Shop chạy cùng tuần trên hai mẫu giày gần như giống hệt nhau (hoặc dùng công cụ thử của sàn nếu có), giữ nguyên tiêu đề, chỉ khác ảnh chính: A nền trắng, B ảnh giày đang mang trên chân chạy bộ. Mỗi bản 12.000 hiển thị (số minh hoạ). A được 180 lượt bấm (1,5%), B được 288 lượt (2,4%). Chênh 0,9 điểm phần trăm, đủ lớn so với dao động thường gặp giữa các tuần của shop (khoảng ±0,2 điểm), nên shop thử kiểu ảnh này trên vài mẫu cùng nhóm trước khi nhân rộng. Rồi chạy song song, cùng ảnh B, hai tiêu đề 120 và 60 ký tự: CTR 2,4% và 2,5%, chênh 0,1 điểm, nhỏ hơn dao động, nên chưa thấy tiêu đề tạo khác biệt. Lưu ý: nếu chỉ so tuần này với tuần trước, mùa vụ và đợt sale lẫn vào kết quả (xem module tn02).',
  takeaway:'Thử từng yếu tố một, bắt đầu từ thứ khách nhìn thấy trước — thường là ảnh chính.',
  apply:'Chọn một sản phẩm bạn đang bán online. Nói trong 60 giây: yếu tố nào khách thấy đầu tiên, bạn sẽ thử phiên bản nào thay thế, và đo bằng chỉ số gì.',
  mistakes:['Đổi ảnh, tiêu đề, giá cùng một lúc rồi không biết cái gì tạo ra kết quả.','Chỉ tối ưu tiêu đề cho từ khoá mà quên ảnh chính mới là thứ khiến người ta bấm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trường hợp nào shop nên thử tiêu đề trước, thay vì ảnh chính?',
    options:[{k:'a',t:'Khi ảnh chính trông đã đẹp mắt, vì lúc đó chỉ còn tiêu đề để sửa'},{k:'b',t:'Khi giá thấp hơn đối thủ cùng loại, vì giá rẻ sẽ tự bù cho tiêu đề yếu'},
             {k:'c',t:'Khi hiển thị rất thấp, vì tiêu đề quyết định bạn có hiện ra khi khách tìm'},{k:'d',t:'Khi muốn tiết kiệm thời gian, vì sửa chữ luôn nhanh hơn chụp lại ảnh'}],
    answer:'c', why:{a:'Ảnh "đẹp" là cảm nhận của chủ shop; chưa có CTR so sánh thì chưa biết ảnh đã tốt chưa.',
      b:'Giá chỉ tác động sau khi khách đã bấm hoặc đã thấy sản phẩm; nó không cứu một sản phẩm không hiện ra.',
      c:'Đúng. Ảnh chỉ có tác dụng với người đã nhìn thấy thẻ sản phẩm; nếu ít người thấy, vấn đề nằm ở chuyện có xuất hiện hay không.',
      d:'Nhanh không phải tiêu chí chọn thử gì; chọn theo chỗ nghẽn trong phễu: hiển thị hay bấm.'} },
  { type:'mcq', stem:'Tỉ lệ bấm thấp nhưng hiển thị ổn. Chủ shop có một buổi chiều để thiết kế phép thử. Bạn chọn cách nào?',
    options:[{k:'a',t:'Đổi cả ảnh, tiêu đề và giá cùng lúc để tăng tối đa khả năng cải thiện ngay'},{k:'b',t:'Chạy hai bản ảnh song song cho hai nhóm hiển thị, chỉ khác ảnh chính, rồi so tỉ lệ bấm'},
             {k:'c',t:'Chỉ đổi tiêu đề trước, vì sửa chữ nhanh và thuật toán sàn ưu tiên từ khoá'},{k:'d',t:'Giảm giá 10% trước, vì giá mới là thứ quyết định người mua có bấm hay không'}],
    answer:'b', why:{a:'Đổi nhiều thứ cùng lúc thì không học được gì để áp dụng cho sản phẩm khác.',
      b:'Đúng. Hai nhóm chạy cùng lúc nên mùa vụ và đợt sale tác động như nhau; chênh lệch còn lại là do ảnh.',
      c:'Tiêu đề quan trọng nhưng khi hiển thị đã ổn mà ít người bấm, nghi ngờ đầu tiên là ảnh.',
      d:'Giảm giá tốn lãi và là thử giá chứ không phải thử creative.'} },
  { type:'calc', stem:'Ảnh mới có 12.000 lượt hiển thị và 288 lượt bấm. Tỉ lệ bấm (CTR) là bao nhiêu phần trăm?',
    unit:'%', ans:2.4, tol:0.05, wrong:[[41.7,'SAI_MAU_SO'],[0.24,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['CTR = lượt bấm ÷ lượt hiển thị.','288 ÷ 12.000 = 0,024 = <b>2,4%</b>.'] },
  { type:'mcq', stem:'CTR tăng từ 1,5% lên 2,4% nhưng số đơn không đổi. Nên kiểm tra điều gì tiếp?',
    options:[{k:'a',t:'Kết luận ảnh mới vô dụng và quay về ảnh nền trắng cũ'},{k:'b',t:'Tăng ngân sách quảng cáo ngay vì CTR tốt thì sớm muộn đơn sẽ về'},
             {k:'c',t:'Trang sản phẩm có khớp với ảnh hứa hẹn không, và tỉ lệ đặt hàng sau bấm'},{k:'d',t:'Đổi tiêu đề tiếp, vì tiêu đề là nguyên nhân khiến đơn không tăng'}],
    answer:'c', why:{a:'Ảnh mới làm đúng việc của nó là kéo người vào; vấn đề có thể nằm sau cú bấm.',
      b:'Bơm tiền khi chưa hiểu vì sao đơn không tăng dễ làm phí thêm.',
      c:'Đúng. CTR và tỉ lệ chuyển đổi là hai tầng khác nhau; cần xem tầng sau.',
      d:'Chưa có bằng chứng tiêu đề là nguyên nhân; hãy xem trang sản phẩm trước.'} },
  { type:'mcq', stem:'Một tiệm bánh mì chạy quảng cáo tìm kiếm. Họ muốn thử tiêu đề quảng cáo. Cách nào đúng?',
    options:[{k:'a',t:'Giữ hình và mô tả, chỉ đổi dòng tiêu đề giữa hai bản chạy cùng lúc'},{k:'b',t:'Chạy tiêu đề A tháng này, tiêu đề B tháng sau rồi so doanh số cả tháng'},
             {k:'c',t:'Viết mười tiêu đề và để cả mười chạy cùng lúc với ngân sách rất nhỏ'},{k:'d',t:'Hỏi khách quen ở quầy thích tiêu đề nào hơn rồi chọn theo số đông'}],
    answer:'a', why:{a:'Đúng. Chạy song song và chỉ khác một yếu tố thì so sánh mới công bằng.',
      b:'Hai tháng khác nhau về mùa vụ và thời tiết; chênh lệch không chỉ do tiêu đề.',
      c:'Ngân sách nhỏ chia mười thì mỗi bản quá ít dữ liệu để kết luận.',
      d:'Khách quen không đại diện cho người đang tìm kiếm, và nói thích khác với bấm.'} },
  { type:'mcq', stem:'Sau khi ảnh "giày trên chân" thắng, shop nên làm gì với 20 mẫu giày khác?',
    options:[{k:'a',t:'Giữ ảnh nền trắng cho các mẫu khác, vì mỗi sản phẩm là một trường hợp riêng'},{k:'b',t:'Đổi hết 20 mẫu ngay lập tức mà không cần theo dõi thêm gì nữa'},
             {k:'c',t:'Chờ thêm sáu tháng để loại hẳn khả năng kết quả do may mắn'},{k:'d',t:'Áp dụng cho vài mẫu cùng nhóm, theo dõi CTR rồi mới nhân rộng'}],
    answer:'d', why:{a:'Một phép thử chưa phải quy luật, nhưng bỏ hẳn thì mất cơ hội; nên mở rộng có kiểm soát.',
      b:'Một phép thử trên một mẫu chưa đủ để đổi cả 20 mẫu; mẫu khác có thể không hợp.',
      c:'Chờ quá lâu làm mất doanh số; thử vài mẫu đã đủ để học thêm.',
      d:'Đúng. Thử vài mẫu cùng nhóm cho biết bài học có lan sang mẫu khác không, rồi mới nhân rộng.'} },
  { type:'mcq', stem:'Tiêu đề 120 ký tự nhồi từ khoá có nhược điểm gì với người mua trên điện thoại?',
    options:[{k:'a',t:'Làm sàn khoá sản phẩm vì vi phạm chính sách về độ dài tiêu đề'},{k:'b',t:'Phần hiển thị bị cắt, điều quan trọng nhất có thể bị đẩy ra khỏi màn hình'},
             {k:'c',t:'Khiến giá hiển thị nhỏ lại, người mua không đọc được giá sản phẩm'},{k:'d',t:'Làm ảnh chính bị thu nhỏ vì tiêu đề chiếm quá nhiều diện tích trên thẻ'}],
    answer:'b', why:{a:'Đề không nói sàn xử lý độ dài tiêu đề ra sao; nhược điểm cần nêu nằm ở chỗ người đọc nhìn thấy gì.',
      b:'Đúng. Điện thoại chỉ hiện vài chục ký tự đầu; điều bán hàng phải nằm ở đó.',
      c:'Độ dài tiêu đề không đổi cỡ chữ của giá.',
      d:'Bố cục thẻ sản phẩm thường cố định; tiêu đề dài chỉ bị cắt.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tn03-04', skill:'creative', read:'7 phút', t:'Hai thông điệp, hai hình ảnh: cần chạy mấy bản?',
  situation:'Một app học tiếng Anh có hai thông điệp: "Nói tự tin sau 30 ngày" và "Chỉ 10 phút mỗi ngày". Họ cũng có hai kiểu hình: người đi làm trong văn phòng và sinh viên ở quán cà phê. Trưởng nhóm muốn biết nên ghép cặp nào, hay cứ chạy một bản "đẹp nhất" cho nhanh.',
  concept:{ name:'Ma trận thử: thông điệp × hình ảnh',
    body:'Khi có hai yếu tố, mỗi yếu tố hai lựa chọn, bạn ghép thành <b>ma trận 2 × 2</b> gồm bốn bản. Nhìn theo hàng biết thông điệp nào mạnh hơn trung bình; nhìn theo cột biết hình nào mạnh hơn; nhìn ô biết cặp nào hợp nhau bất thường. Ma trận cho nhiều bài học hơn thử từng cặp riêng lẻ. Nhưng số ô tăng rất nhanh: 3 × 3 là 9 bản, mỗi bản cần đủ lượt hiển thị. Ngân sách nhỏ thì chỉ nên làm ma trận nhỏ.' },
  example:'Bốn bản, mỗi bản 20.000 hiển thị. Tỉ lệ cài app: "30 ngày + văn phòng" 1,2%; "30 ngày + sinh viên" 0,8%; "10 phút + văn phòng" 1,6%; "10 phút + sinh viên" 1,0%. Theo hàng, "10 phút" trung bình 1,3% so với 1,0%. Theo cột, "văn phòng" trung bình 1,4% so với 0,9%. Đội chọn "10 phút + văn phòng", và ghi lại rằng người đi làm quan tâm thời gian hơn lời hứa kết quả.',
  takeaway:'Ghép yếu tố thành ma trận nhỏ để biết cả cái gì thắng lẫn vì sao nó thắng.',
  points:["Mỗi mức của một yếu tố được thử ở cả hai mức của yếu tố kia, nên hàng và cột gom được số liệu của hai ô. Cùng ngân sách, thông tin nhiều hơn.","Các ô phải có số hiển thị ngang nhau, như 20.000 mỗi bản. Ô quá ít lượt sẽ kéo trung bình hàng hoặc cột lệch theo may rủi.","Ma trận còn cho thấy tương tác: thông điệp có thể mạnh với hình này mà yếu với hình kia. Chỉ nhìn từng ô, so với mức hàng và cột gợi ý, mới thấy."],
  counter:"Giả sử app tiếng Anh chỉ đủ ngân sách cho khoảng 8.000 hiển thị mà vẫn chạy bốn bản, mỗi bản 2.000 lượt. Với tỉ lệ cài quanh 1,2%, mỗi ô chỉ có khoảng 24 lượt cài, nên chênh 1,2% với 1,6% có thể chỉ là may rủi. Dấu hiệu nhận ra: chạy lại thì thứ tự các ô xáo trộn. Lúc đó rút về thử một yếu tố với hai bản.",
  deeper:"Người làm nghề hỏi: yếu tố nào đáng đưa vào ma trận? Chỉ những yếu tố mà kết quả sẽ đổi quyết định tiếp theo. Đánh đổi là số ô tăng nhanh, nên thường giữ 2 × 2 và nối nhiều vòng với nhau. Tín hiệu cần theo dõi là khoảng cách giữa các hàng so với khoảng cách giữa các ô cùng hàng: nếu ô cùng hàng chênh nhau nhiều hơn hàng với hàng, yếu tố còn lại mới là chủ. Phép kiểm tra trong tuần: lấy bốn creative sẵn có, xếp thành 2 × 2, và viết ra trước khi chạy bạn đoán hàng nào, cột nào mạnh hơn.",
  apply:'Lấy hai thông điệp và hai hình bạn đang cân nhắc. Nói trong 60 giây: bốn ô ma trận là gì, và bạn cần bao nhiêu hiển thị cho mỗi ô.',
  mistakes:['Làm ma trận 4 × 4 với ngân sách nhỏ, mỗi ô chỉ vài trăm hiển thị nên không kết luận được.','Chỉ nhìn ô thắng mà bỏ qua bài học theo hàng và theo cột.'],
  q:[
  { type:'mcq', stem:'Đoán trước: thử 2 thông điệp và 2 hình ảnh theo ma trận thì cần bao nhiêu bản quảng cáo?',
    options:[{k:'a',t:'2 bản, vì mỗi thông điệp đi với một hình là đủ để so sánh'},{k:'b',t:'4 bản, mỗi thông điệp ghép với từng hình ảnh'},
             {k:'c',t:'8 bản, vì phải tính thêm mỗi yếu tố chạy riêng lẻ không ghép cặp'},{k:'d',t:'3 bản, vì bản thứ tư sẽ trùng lặp thông tin với ba bản kia'}],
    answer:'b', why:{a:'Hai bản thì thông điệp và hình bị trộn lẫn, không tách được cái nào tạo khác biệt.',
      b:'Đúng. 2 × 2 = 4 ô.',
      c:'Quảng cáo luôn có cả chữ và hình; không có bản "riêng lẻ" để thêm vào.',
      d:'Thiếu một ô thì không so được theo hàng và cột một cách cân bằng.'} },
  { type:'mcq', stem:'Ngân sách đủ cho khoảng 80.000 hiển thị. Bạn chọn thiết kế thử nào?',
    options:[{k:'a',t:'Ma trận 4 × 4 để khám phá tối đa, mỗi ô khoảng 5.000 hiển thị'},{k:'b',t:'Một bản đẹp nhất, dồn hết ngân sách'},
             {k:'c',t:'Ma trận 3 × 3 cho 9 ô, mỗi ô khoảng 9.000 hiển thị để cân bằng'},{k:'d',t:'Ma trận 2 × 2, mỗi ô 20.000 hiển thị'}],
    answer:'d', why:{a:'5.000 hiển thị với tỉ lệ cài khoảng 1% chỉ ra vài chục lượt; nhiễu quá lớn.',
      b:'Không thử thì không học được gì, và bản "đẹp nhất" chỉ là ý kiến.',
      c:'9 ô chia mỏng ngân sách; mỗi ô vẫn khá ít dữ liệu để kết luận.',
      d:'Đúng. Ít ô, mỗi ô đủ dữ liệu, vẫn đọc được theo hàng và cột.'} },
  { type:'calc', stem:'Hàng "10 phút": ô văn phòng 1,6%, ô sinh viên 1,0%, mỗi ô cùng 20.000 hiển thị. Tỉ lệ cài trung bình của thông điệp "10 phút" là bao nhiêu phần trăm?',
    unit:'%', ans:1.3, tol:0.05, wrong:[[2.6,'SAI_MAU_SO'],[1.6,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Hai ô có cùng số hiển thị nên lấy trung bình cộng.','(1,6 + 1,0) ÷ 2 = <b>1,3%</b>.'] },
  { type:'mcq', stem:'Đọc theo cột, hình "văn phòng" trung bình 1,4%, "sinh viên" 0,9%. Bài học rút ra là gì?',
    options:[{k:'a',t:'Hình người đi làm hợp với tệp khách này hơn, bất kể thông điệp nào'},{k:'b',t:'Sinh viên không cần học tiếng Anh nên có thể bỏ hẳn tệp này'},
             {k:'c',t:'Hình văn phòng đẹp hơn về thẩm mỹ nên kéo được nhiều cài đặt'},{k:'d',t:'Chỉ ô thắng mới có ý nghĩa, còn trung bình theo cột thì không'}],
    answer:'a', why:{a:'Đúng. Hình văn phòng thắng ở cả hai thông điệp, nên đó là bài học về hình, không riêng một cặp.',
      b:'Tệp chạy quảng cáo có thể không nhiều sinh viên; không suy ra được sinh viên không cần học.',
      c:'Dữ liệu cho biết hình nào hiệu quả, không nói gì về thẩm mỹ.',
      d:'Trung bình theo cột chính là phần giúp áp dụng bài học cho bản sau.'} },
  { type:'mcq', stem:'Một quán cà phê thử 2 câu chữ × 2 ảnh, nhưng mỗi ô chỉ có khoảng 400 lượt hiển thị. Nên đọc kết quả thế nào?',
    options:[{k:'a',t:'Chọn ngay ô có nhiều lượt bấm nhất và dừng thử để tiết kiệm tiền'},{k:'b',t:'Cộng dồn theo hàng hoặc cột để có nhiều dữ liệu hơn, kết luận thận trọng'},
             {k:'c',t:'Kết luận rằng creative không quan trọng vì các ô trông gần bằng nhau'},{k:'d',t:'Bỏ ma trận, lần sau chỉ chạy một bản cho đỡ tốn công theo dõi'}],
    answer:'b', why:{a:'Với 400 hiển thị, chênh vài lượt bấm có thể chỉ là ngẫu nhiên.',
      b:'Đúng. Gộp theo hàng/cột cho mỗi so sánh 800 hiển thị, đỡ nhiễu hơn từng ô.',
      c:'Ít dữ liệu thì không phân biệt được; không có nghĩa là không có khác biệt.',
      d:'Vấn đề là ma trận quá mỏng so với ngân sách; nên thu nhỏ hoặc chạy lâu hơn.'} },
  { type:'mcq', stem:'Ở một lần thử khác, một ô cao hơn hẳn mức mà hàng và cột gợi ý. (Trong ví dụ trên, ô "10 phút + văn phòng" chỉ cao hơn mức đó khoảng 0,05 điểm nên chưa phải dấu hiệu này.) Điều này có thể nghĩa là gì?',
    options:[{k:'a',t:'Dữ liệu bị lỗi, vì ô không thể cao hơn trung bình hàng và cột'},{k:'b',t:'Thông điệp và hình không liên quan gì đến nhau, chỉ là trùng hợp'},
             {k:'c',t:'Hai yếu tố trong ô đó hợp nhau đặc biệt, củng cố lẫn nhau'},{k:'d',t:'Nên bỏ ngay các ô còn lại mà không cần ghi chép gì về chúng'}],
    answer:'c', why:{a:'Ô cao hơn trung bình là bình thường; đó chính là dấu hiệu tương tác giữa hai yếu tố.',
      b:'Ma trận được dựng để phát hiện đúng sự "hợp nhau" này.',
      c:'Đúng. Thông điệp và hình củng cố nhau, đáng ghi vào thư viện bài học.',
      d:'Các ô thua cũng là bài học; ghi lại để lần sau không thử lại.'} },
  { type:'mcq', stem:'Vì sao thử từng cặp riêng lẻ (A1 rồi B2) kém hơn ma trận 2 × 2?',
    options:[{k:'a',t:'Vì hai bản khác cả chữ lẫn hình, không biết khác biệt nhờ yếu tố nào'},{k:'b',t:'Vì nền tảng quảng cáo không cho chạy chỉ hai bản cùng một lúc'},
             {k:'c',t:'Vì chạy lần lượt hai bản tốn nhiều tiền hơn chạy bốn bản cùng lúc'},{k:'d',t:'Vì kết quả của hai bản thường sát nhau nên khó so sánh được'}],
    answer:'a', why:{a:'Đúng. A1 và B2 khác nhau hai chỗ, nên chênh lệch không quy được cho yếu tố nào.',
      b:'Nền tảng cho phép chạy hai bản; vấn đề là thiết kế thử.',
      c:'Hai bản thường rẻ hơn bốn bản; lợi thế của ma trận là thông tin, không phải giá.',
      d:'Hai bản vẫn có thể khác nhau; chỉ là khó giải thích vì sao.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tn03-05', skill:'measure', read:'7 phút', t:'Thumb-stop, xem hết, CTR: chỉ số nào nói gì?',
  situation:'Một thương hiệu đồ ăn vặt chạy hai video trên Facebook. Video A có tỉ lệ dừng lướt 35% nhưng chỉ 8% xem hết. Video B có tỉ lệ dừng lướt 22% nhưng 20% xem hết và CTR cao hơn. Trưởng nhóm hỏi: "Rốt cuộc bản nào tốt hơn?"',
  concept:{ name:'Đọc chỉ số creative theo tầng',
    body:'Mỗi chỉ số đo một tầng của video. <b>Thumb-stop rate</b> (tỉ lệ xem quá 3 giây trên lượt hiển thị) đo sức giữ ngón tay. <b>Tỉ lệ xem hết</b> đo nội dung có đủ hấp dẫn để người ta ở lại. <b>CTR</b> đo lời kêu gọi có đủ thuyết phục để người ta bấm. Một video có thể giỏi tầng này, kém tầng kia. Đọc theo tầng giúp bạn biết cần sửa phần nào: hook, thân video hay lời kêu gọi, thay vì bỏ cả video.' },
  example:'Video A: hook gây sốc (bánh nổ tung) nên 35% dừng lại, nhưng phần sau là giới thiệu thành phần khô khan nên chỉ 8% xem hết, CTR 0,6%. Video B: mở nhẹ hơn, 22% dừng, nhưng kể chuyện ăn vặt giờ tan ca nên 20% xem hết, CTR 1,1%. Mục tiêu là bán hàng, nên B thắng. Đội thử tiếp bản mới: hook của A ghép thân video của B.',
  takeaway:'Mỗi chỉ số chỉ vào một phần của video; đọc theo tầng để biết sửa phần nào, không chỉ chọn bản nào.',
  points:["Phễu xem video có thứ tự: dừng lại, ở lại, bấm. Tầng sau chỉ có người khi tầng trước đã qua, nên số người tới CTR là phần còn lại sau hai tầng.","Mỗi tầng do một phần video quyết định: hook cho người dừng, thân video cho người ở lại, lời kêu gọi cho người bấm. Biết tầng yếu là biết dựng lại đoạn nào.","Chỉ số cuối phải chọn theo mục tiêu. Với bán hàng, CTR và đơn hàng đứng trên, còn tỉ lệ dừng lướt chỉ để chẩn đoán video có thu hút đúng người không."],
  counter:"Giả sử video B chạy cho tệp rộng, nên câu chuyện giờ tan ca kéo cả người không có ý định mua. CTR cao nhưng đơn vẫn thấp vì khách bấm rồi không đặt. Dấu hiệu nhận ra: CTR tốt mà tỉ lệ đặt hàng ở trang đích thấp. Khi đó vấn đề không nằm ở creative; hãy xem lại trang đích, giá và tệp nhắm.",
  deeper:"Người làm nghề không tìm một chỉ số thần kỳ mà đọc cả bộ như một bản chẩn đoán. Đánh đổi: tối ưu mạnh tỉ lệ dừng lướt dễ dẫn tới hook giật gân làm tụt tỉ lệ xem hết, còn tối ưu CTR có thể kéo người bấm nhầm. Tín hiệu cần theo dõi là chỗ video rơi người xem giữa chừng và chi phí mỗi đơn ở cuối phễu. Khái niệm kề cận là thử hook, vì ghép hook của A với thân của B chính là sửa từng tầng. Phép kiểm tra trong tuần: lấy hai video đang chạy, kẻ bảng ba cột thumb-stop, xem hết, CTR và gạch dưới tầng yếu nhất của mỗi video.",
  apply:'Mở báo cáo một video của bạn. Nói trong 60 giây: tầng nào đang rơi mạnh nhất, và bạn sẽ sửa phần nào của video.',
  mistakes:['Chọn video có thumb-stop cao nhất mà không xem người xem có ở lại hay bấm không.','Bỏ cả video kém, trong khi chỉ một phần của nó yếu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: video có tỉ lệ dừng lướt cao nhất có phải luôn là video bán tốt nhất không?',
    options:[{k:'a',t:'Có, vì nhiều người dừng lại thì nhiều người sẽ mua theo tỉ lệ'},{k:'b',t:'Có, vì thuật toán đẩy video giữ chân tốt đến người sẵn sàng mua'},
             {k:'c',t:'Không, vì thumb-stop chỉ đo ba giây đầu, các tầng sau vẫn có thể rơi'},{k:'d',t:'Không, vì thumb-stop là chỉ số ảo, không liên quan gì đến kinh doanh'}],
    answer:'c', why:{a:'Dừng lại chưa phải quan tâm; nhiều người dừng vì tò mò rồi đi.',
      b:'Thuật toán có ưu tiên video giữ chân, nhưng không đảm bảo người xem mua.',
      c:'Đúng. Đó là tầng đầu; cần xem thêm tỉ lệ xem hết và CTR.',
      d:'Thumb-stop hữu ích để đánh giá hook; chỉ là không đủ một mình.'} },
  { type:'mcq', stem:'Mục tiêu là bán hàng. Với số liệu A và B ở trên, bạn chọn làm gì?',
    options:[{k:'a',t:'Dồn tiền cho A vì A thu hút nhiều người dừng lại xem nhất'},{k:'b',t:'Dồn tiền cho B, đồng thời thử bản ghép hook của A với thân video B'},
             {k:'c',t:'Tắt cả hai vì không bản nào có đủ ba chỉ số cao cùng một lúc'},{k:'d',t:'Chia đều ngân sách cho cả hai để nền tảng tự tối ưu dần theo thời gian'}],
    answer:'b', why:{a:'A kéo người dừng nhưng không giữ và không thuyết phục bấm.',
      b:'Đúng. B gần mục tiêu hơn; bản ghép tận dụng điểm mạnh của từng video.',
      c:'Hiếm video nào mạnh cả ba tầng; nên cải thiện chứ không bỏ hết.',
      d:'Đã có bằng chứng; chia đều là bỏ phí phần tiền cho bản yếu hơn.'} },
  { type:'calc', stem:'Video B có 50.000 lượt hiển thị, 11.000 người xem quá 3 giây. Thumb-stop rate là bao nhiêu phần trăm?',
    unit:'%', ans:22, tol:0.1, wrong:[[454.5,'SAI_MAU_SO'],[2.2,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Thumb-stop = lượt xem quá 3 giây ÷ lượt hiển thị.','11.000 ÷ 50.000 = 0,22 = <b>22%</b>.'] },
  { type:'mcq', stem:'Một video có thumb-stop 30%, xem hết 25% nhưng CTR chỉ 0,3%. Phần nào đáng sửa trước?',
    options:[{k:'a',t:'Hook, vì phần mở đầu là nơi kéo theo các chỉ số phía sau'},{k:'b',t:'Thân video, vì người xem đang bỏ đi trước khi xem hết nội dung'},
             {k:'c',t:'Lời kêu gọi hành động và điều khiến người ta có lý do bấm'},{k:'d',t:'Thời lượng, vì video càng dài thì càng ít người bấm vào liên kết'}],
    answer:'c', why:{a:'Hook đang làm tốt hơn các chỉ số còn lại; 30% dừng lại là mức khá trong ví dụ này (không có mốc chung cho mọi ngành, hãy so với video cũ của chính bạn).',
      b:'25% xem hết là tốt; người xem đang ở lại.',
      c:'Đúng. Người ta xem hết nhưng không bấm: lời mời bấm hoặc ưu đãi đang yếu.',
      d:'Họ đã xem hết rồi; độ dài không phải chỗ gãy.'} },
  { type:'mcq', stem:'Tỉ lệ xem hết của video 60 giây là 10%, video 15 giây là 30%. Kết luận nào cẩn thận nhất?',
    options:[{k:'a',t:'Video 15 giây hấp dẫn hơn gấp ba lần nên nên chọn video ngắn'},{k:'b',t:'Video 60 giây thất bại, nên bỏ hẳn định dạng video dài từ nay'},
             {k:'c',t:'Hai con số bằng nhau về ý nghĩa vì đều là tỉ lệ phần trăm'},{k:'d',t:'Không so thẳng được; video dài hơn tự nhiên có tỉ lệ xem hết thấp hơn'}],
    answer:'d', why:{a:'Độ dài khác nhau nên tỉ lệ xem hết không cùng thước đo.',
      b:'10% xem hết một video 60 giây có thể là tốt; phải so với video cùng độ dài.',
      c:'Cùng đơn vị không có nghĩa cùng điều kiện; độ dài làm thay đổi mức nền.',
      d:'Đúng. So tỉ lệ xem hết giữa các video cùng độ dài, hoặc xem thời gian xem trung bình.'} },
  { type:'mcq', stem:'Một tiệm hoa chạy video Valentine: CTR 2% nhưng tỉ lệ đặt hàng trên web chỉ 0,5%. Creative có phải thủ phạm chính?',
    options:[{k:'a',t:'Có lẽ không; creative đã kéo người bấm, chỗ gãy nằm ở trang đặt hàng'},{k:'b',t:'Có, vì creative là thứ khách thấy đầu tiên nên gánh doanh số cuối'},
             {k:'c',t:'Có, vì CTR 2% là quá thấp so với mùa cao điểm như Valentine'},{k:'d',t:'Không thể biết gì nếu chưa chạy thêm ít nhất ba tháng nữa để có đủ dữ liệu'}],
    answer:'a', why:{a:'Đúng. Bấm tốt nhưng không mua: xem giá, phí ship, tốc độ trang, hoặc lời hứa lệch với trang.',
      b:'Creative ảnh hưởng nhưng không gánh cả phễu; đọc theo tầng để khoanh vùng.',
      c:'Không có mốc chung như vậy; và vấn đề rõ ràng hơn nằm ở tầng sau.',
      d:'Dữ liệu hiện có đã đủ để khoanh vùng tầng gãy; chờ ba tháng là bỏ qua mùa.'} },
  { type:'mcq', stem:'Vì sao ghép hook của A với thân của B là một thử nghiệm hợp lý?',
    options:[{k:'a',t:'Vì hai video ghép lại sẽ cộng được điểm mạnh của cả hai bản'},{k:'b',t:'Vì nền tảng ưu tiên video được dựng lại từ các quảng cáo cũ đã chạy'},
             {k:'c',t:'Vì đọc theo tầng cho thấy mỗi video mạnh ở một phần khác nhau'},{k:'d',t:'Vì ghép video tiết kiệm chi phí hơn quay một video mới từ đầu'}],
    answer:'c', why:{a:'Chưa chắc; hook sốc có thể không khớp phần kể chuyện, nên mới cần thử.',
      b:'Không có ưu tiên như vậy.',
      c:'Đúng. Giả thuyết đến từ việc đọc chỉ số theo tầng.',
      d:'Rẻ là điểm cộng, nhưng lý do chính là giả thuyết có căn cứ từ dữ liệu.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tn03-06', skill:'creative', read:'6 phút', t:'Quảng cáo đang thắng bỗng hụt hơi: khi nào thay?',
  situation:'Một thương hiệu nệm cao su chạy một video suốt năm tuần. Tuần đầu CTR 1,6%, chi phí mỗi đơn 180.000 đồng. Đến tuần năm, CTR còn 0,9%, chi phí mỗi đơn lên 310.000 đồng, trong khi tần suất trung bình tăng từ 1,4 lên 4,2 lần mỗi người. Đội đang tranh luận có nên tăng ngân sách để "đẩy" lại.',
  concept:{ name:'Creative mỏi (creative fatigue)',
    body:'Khi cùng một nhóm người thấy cùng một quảng cáo quá nhiều lần, họ bắt đầu bỏ qua nó. Đó là <b>creative mỏi</b>. Dấu hiệu thường đi cùng nhau: tần suất tăng, CTR giảm dần, chi phí mỗi kết quả tăng. Thời điểm mỏi không cố định: tệp nhỏ và ngân sách lớn thì mỏi nhanh, tệp rộng thì lâu hơn. Cách phòng là chuẩn bị sẵn vài biến thể để thay dần, thay vì chờ đến khi hiệu quả đã sụp.' },
  example:'Đội vẽ ba đường theo tuần: tần suất 1,4 → 2,1 → 2,9 → 3,6 → 4,2; CTR 1,6% → 1,5% → 1,3% → 1,1% → 0,9%. Điểm gãy rõ từ tuần ba, khi tần suất vượt khoảng 2,5. Thay vì tăng ngân sách, họ đưa vào hai biến thể có hook mới đã chuẩn bị sẵn. Tuần sáu, CTR trung bình quay về 1,4%. Họ ghi lại: với tệp này, lên lịch thay creative khoảng mỗi hai đến ba tuần.',
  takeaway:'Theo dõi tần suất cùng CTR; khi tần suất tăng mà CTR giảm dần, thay creative trước khi tăng tiền.',
  points:["Quảng cáo mỏi vì cùng một nhóm người bị nhắc đi nhắc lại, mỗi lần thấy lại chú ý ít đi. Tần suất đo độ lặp này, nên thường báo trước khi CTR sụt.","Tăng ngân sách cho creative đã mỏi chỉ ép cùng nhóm người xem nhiều lần hơn, nên tần suất vọt lên và chi phí mỗi đơn tệ thêm. Cần creative mới.","Điểm gãy nên đọc theo từng tệp, trên đường tần suất và CTR của tệp đó. Ở tệp này điểm gãy khoảng tần suất 2,5, nên đặt mốc cảnh báo thấp hơn."],
  counter:"Giả sử cũng thương hiệu nệm, nhưng CTR giảm vì nhu cầu theo mùa hạ xuống hoặc đối thủ vừa giảm giá mạnh. Tần suất lúc này vẫn thấp, khoảng 1,5, mà CTR vẫn tụt. Dấu hiệu nhận ra: tần suất không tăng nhiều, và các quảng cáo khác trong cùng tệp cũng sụt theo. Thay creative lúc này chỉ tốn công; hãy xem lại mùa vụ, giá đấu thầu và động thái của đối thủ.",
  deeper:"Người làm nghề đứng giữa hai nỗi sợ: thay quá sớm thì bỏ phí creative còn tốt, thay quá muộn thì trả giá bằng tiền đã đốt. Cách giải thường là lịch thay dựa vào dữ liệu của từng tệp, không dùng một con số cố định cho nhiều chiến dịch. Tín hiệu cần theo dõi là tần suất, CTR và chi phí mỗi đơn, đọc cùng nhau. Khái niệm kề cận là thử hook, vì biến thể thay thế nên là hook mới trên cùng thân video. Phép kiểm tra trong tuần: vẽ ba đường tần suất, CTR, chi phí mỗi đơn của một chiến dịch đang chạy và tìm điểm gãy đầu tiên.",
  apply:'Mở quảng cáo đang chạy lâu nhất của bạn. Nói trong 60 giây: tần suất và CTR đã đi thế nào theo tuần, và biến thể thay thế đã sẵn sàng chưa.',
  mistakes:['Tăng ngân sách khi quảng cáo đã mỏi, làm tần suất càng cao và chi phí càng tăng.','Áp một con số "mỏi sau X ngày" cho mọi chiến dịch mà không xem dữ liệu của mình.'],
  q:[
  { type:'mcq', stem:'Đoán trước: quảng cáo chạy tốt tuần đầu rồi giảm dần. Nguyên nhân thường gặp nhất là gì?',
    options:[{k:'a',t:'Người xem cũ thấy lại quá nhiều lần nên bắt đầu lướt qua quảng cáo'},{k:'b',t:'Nền tảng cố tình giảm hiệu quả để buộc thương hiệu phải trả thêm tiền'},
             {k:'c',t:'Sản phẩm đột nhiên kém chất lượng hơn so với tuần đầu tiên chạy'},{k:'d',t:'Đối thủ đã sao chép y hệt video nên khách bị nhầm lẫn thương hiệu'}],
    answer:'a', why:{a:'Đúng. Tần suất tăng thì sự chú ý giảm; đó là creative mỏi.',
      b:'Không có căn cứ; hiện tượng mỏi giải thích được bằng hành vi người xem.',
      c:'Không có dấu hiệu sản phẩm thay đổi; chỉ số giảm song song với tần suất tăng.',
      d:'Có thể xảy ra nhưng hiếm; nguyên nhân phổ biến hơn là người xem đã quen.'} },
  { type:'mcq', stem:'Tuần năm: tần suất 4,2, CTR 0,9%, chi phí mỗi đơn 310.000 đồng. Bạn làm gì?',
    options:[{k:'a',t:'Tăng gấp đôi ngân sách để đẩy video tới thêm nhiều người mới'},{k:'b',t:'Giữ nguyên thêm hai tuần nữa để chờ hiệu quả tự hồi phục'},
             {k:'c',t:'Tắt quảng cáo hẳn và chờ đến chiến dịch lớn tiếp theo mới chạy lại'},{k:'d',t:'Thay dần bằng các biến thể mới, theo dõi CTR và chi phí mỗi đơn'}],
    answer:'d', why:{a:'Ngân sách tăng trên tệp cũ thường làm tần suất tăng thêm, mỏi nặng hơn.',
      b:'Mỏi hiếm khi tự hồi phục khi vẫn chiếu cùng một video cho cùng tệp.',
      c:'Tắt hẳn là mất doanh số; vấn đề là creative, không phải kênh.',
      d:'Đúng. Đổi creative giải quyết đúng nguyên nhân; theo dõi để xác nhận.'} },
  { type:'calc', stem:'Chi phí mỗi đơn tăng từ 180.000 lên 310.000 đồng. Tăng bao nhiêu phần trăm so với tuần đầu?',
    unit:'%', ans:72.2, tol:0.2, wrong:[[41.9,'SAI_MAU_SO'],[172.2,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Mức tăng = 310.000 − 180.000 = 130.000.','130.000 ÷ 180.000 ≈ 0,722 = <b>72,2%</b>.'] },
  { type:'mcq', stem:'Một shop mỹ phẩm chạy cho tệp 50.000 người với ngân sách lớn; shop khác chạy cho tệp 2 triệu người với ngân sách nhỏ. Shop nào có khả năng gặp mỏi sớm hơn?',
    options:[{k:'a',t:'Shop tệp lớn, vì nhiều người thấy thì quảng cáo sẽ nhàm nhanh hơn'},{k:'b',t:'Shop tệp nhỏ ngân sách lớn, vì mỗi người thấy lặp lại nhiều lần'},
             {k:'c',t:'Hai shop như nhau, vì creative mỏi chỉ phụ thuộc vào số ngày chạy'},{k:'d',t:'Shop tệp lớn, vì chạy cho 2 triệu người thì dễ bão hoà hơn'}],
    answer:'b', why:{a:'Tệp lớn chia ngân sách cho nhiều người hơn, tần suất mỗi người thấp.',
      b:'Đúng. Tiền nhiều trên tệp nhỏ đẩy tần suất lên nhanh.',
      c:'Thời gian là một yếu tố, nhưng tần suất phụ thuộc tệp và ngân sách.',
      d:'Tệp lớn mà ngân sách nhỏ thì mỗi người thấy ít lần; mỏi đến từ lặp lại trên cùng người.'} },
  { type:'mcq', stem:'Đội quyết định "cứ 14 ngày thay creative một lần cho mọi chiến dịch". Vấn đề của quy tắc này là gì?',
    options:[{k:'a',t:'Quá thường xuyên, vì creative tốt có thể chạy đến vài năm vẫn hiệu quả'},{k:'b',t:'Không có vấn đề gì, vì 14 ngày là mốc chuẩn mà ngành quảng cáo đã dùng'},
             {k:'c',t:'Bỏ qua dữ liệu; mỗi tệp và ngân sách mỏi ở tốc độ khác nhau'},{k:'d',t:'Làm tốn tiền sản xuất nên chỉ doanh nghiệp lớn mới áp dụng nổi'}],
    answer:'c', why:{a:'Có creative chạy lâu, nhưng không thể khẳng định cho mọi trường hợp.',
      b:'Không có mốc chuẩn chung; tự đo mới biết.',
      c:'Đúng. Dùng tín hiệu tần suất và CTR thay cho lịch cứng.',
      d:'Chi phí là một mặt; vấn đề chính là thay theo lịch thay vì theo tín hiệu.'} },
  { type:'mcq', stem:'Cách phòng creative mỏi hiệu quả nhất cho một đội nhỏ là gì?',
    options:[{k:'a',t:'Chuẩn bị sẵn 2–3 biến thể và thay khi tín hiệu mỏi xuất hiện'},{k:'b',t:'Đầu tư quay một video thật đẹp để người xem lâu chán hơn'},
             {k:'c',t:'Tắt quảng cáo vài ngày mỗi tuần để người xem kịp quên video cũ'},{k:'d',t:'Đổi tệp khách mỗi ngày để quảng cáo gặp người chưa thấy'}],
    answer:'a', why:{a:'Đúng. Có hàng chờ thì thay kịp lúc, không để hiệu quả sụp.',
      b:'Video đẹp đến đâu cũng mỏi khi được chiếu quá nhiều lần cho cùng người.',
      c:'Tắt ngắt quãng làm mất đà phân phối mà người xem vẫn nhớ video cũ.',
      d:'Đổi tệp liên tục làm mất dữ liệu tối ưu và có thể đưa quảng cáo tới người không liên quan.'} },
  { type:'mcq', stem:'Sau khi thay creative, CTR quay về 1,4% nhưng tần suất vẫn là 4,0. Điều đó gợi ý gì?',
    options:[{k:'a',t:'Tần suất không liên quan gì tới hiệu quả, có thể bỏ qua chỉ số này'},{k:'b',t:'Người xem mệt vì video cũ, không phải vì thương hiệu hay tệp khách'},
             {k:'c',t:'Tệp khách đã bão hoà, nên cần chuyển sang tệp khác ngay'},{k:'d',t:'Creative mới sẽ không mỏi nữa vì đội đã rút được kinh nghiệm'}],
    answer:'b', why:{a:'Tần suất vẫn quan trọng; nó giải thích vì sao video cũ mỏi.',
      b:'Đúng. Cùng tệp, cùng tần suất, nội dung mới được chú ý lại.',
      c:'CTR hồi phục cho thấy tệp vẫn phản hồi; chưa bão hoà.',
      d:'Creative mới rồi cũng sẽ mỏi; cần tiếp tục theo dõi.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tn03-07', skill:'brand', read:'7 phút', t:'Quảng cáo thắng về click có đang làm hại thương hiệu?',
  situation:'Một thương hiệu dầu gội thảo dược định vị "dịu nhẹ, tự nhiên". Trong đợt thử, bản có chữ đỏ "GIẢM 50% HÔM NAY", ảnh tóc rụng cận cảnh thắng rõ: CTR 2,4% so với 1,2% của bản kể chuyện bà hái bồ kết. Đội performance muốn dồn toàn bộ ngân sách quý cho bản thắng.',
  concept:{ name:'Thắng ngắn hạn vs khớp thương hiệu',
    body:'Chỉ số quảng cáo đo phản ứng tức thời: dừng, bấm, mua. Nhưng mỗi quảng cáo còn để lại một <b>dấu vết trong trí nhớ</b> về thương hiệu. Bản gây giật mình hay giảm giá sâu có thể thắng click nhưng dạy khách rằng "hãng này là hàng giảm giá" hoặc làm lệch định vị. Vì vậy khi chọn bản thắng, cần đặt thêm một câu hỏi: nó có nói đúng mình là ai không? Có thể dùng bản thắng cho phần chuyển đổi, nhưng không để nó trở thành gương mặt duy nhất.' },
  example:'Đội chia ngân sách: 70% cho chuỗi quảng cáo kể chuyện bồ kết (xây nhận diện, chạy dài), 30% cho bản khuyến mãi nhắm người đã xem hoặc vào trang. Sau hai tháng, họ khảo sát nhanh 300 khách: người thấy chủ yếu bản khuyến mãi nhớ thương hiệu là "hay giảm giá"; người thấy bản kể chuyện nhớ "thảo dược, dịu nhẹ". Đội giữ tỉ lệ chia này cho quý sau.',
  takeaway:'Bản thắng click chưa chắc thắng thương hiệu; hỏi thêm nó dạy khách nhớ gì về mình.',
  points:["Click là phản ứng tức thời, còn thương hiệu là ký ức tích luỹ. Hai thứ đo ở hai thời điểm nên bản thắng click vẫn có thể làm mòn ký ức.","Khách nhớ thương hiệu qua thứ thấy lặp lại nhiều nhất. Nếu đó là chữ đỏ khuyến mãi, thương hiệu bị nhớ là hàng giảm giá, dù lời hứa gốc là dịu nhẹ.","Chia vai: bản kể chuyện lo nhận diện cho tệp rộng, bản khuyến mãi lo chốt người đã quan tâm. Mỗi bản được đo bằng chỉ số đúng vai của nó."],
  counter:"Giả sử cũng hãng dầu gội, nhưng là sản phẩm mới ra, chưa có định vị nào để bảo vệ và ngân sách chỉ nuôi nổi một chuỗi. Khi đó bản khuyến mãi có thể là cách nhanh nhất để có đơn đầu tiên và dữ liệu. Dấu hiệu nhận ra: chưa có nhận diện nào để mất. Lúc đó chạy bản chuyển đổi trước, nhưng giữ giọng và hình ảnh không mâu thuẫn với lời hứa.",
  deeper:"Người làm nghề thấy đây là đánh đổi giữa doanh số quý này và giá trị của cái tên về sau. Tín hiệu cần theo dõi là khảo sát nhận diện, tỉ lệ khách nhớ đúng lời hứa, và mức mua khi không có khuyến mãi, thứ mà CTR không đo được. Khái niệm kề cận là creative mỏi: bản khuyến mãi lặp mãi trên một tệp vừa mỏi nhanh vừa càng ghim ấn tượng giảm giá. Phép kiểm tra trong tuần: hỏi nhanh vài chục khách quen rằng họ nghĩ tới điều gì đầu tiên khi nhắc thương hiệu, rồi so với lời hứa định vị.",
  apply:'Chọn quảng cáo thắng gần nhất của bạn. Nói trong 60 giây: nó dạy khách nhớ gì về thương hiệu, và điều đó có khớp định vị không.',
  mistakes:['Chọn creative chỉ theo CTR hay chi phí mỗi đơn, bỏ qua định vị.','Coi quảng cáo thương hiệu và quảng cáo chuyển đổi là đối nghịch, phải chọn một.'],
  q:[
  { type:'mcq', stem:'Đoán trước: bản "GIẢM 50%" thắng CTR gấp đôi. Rủi ro nào dễ bị bỏ qua nhất?',
    options:[{k:'a',t:'Khách bấm nhiều quá khiến website bị quá tải và sập trong đợt chạy'},{k:'b',t:'Chi phí mỗi lượt bấm sẽ tăng vì nền tảng tính giá cao hơn cho bản thắng'},
             {k:'c',t:'Khách chỉ quen mua khi giảm giá và nhớ thương hiệu lệch định vị'},{k:'d',t:'Đối thủ sẽ kiện vì quảng cáo giảm giá sâu vi phạm quy định cạnh tranh'}],
    answer:'c', why:{a:'Rủi ro kỹ thuật có thể xử lý; vấn đề khó thấy hơn nằm ở trí nhớ thương hiệu.',
      b:'CTR cao thường làm chi phí mỗi lượt bấm giảm, không tăng.',
      c:'Đúng. Chỉ số click không đo được điều khách học về thương hiệu.',
      d:'Không nên khẳng định vi phạm; giảm giá tự nó không phải vấn đề pháp lý.'} },
  { type:'mcq', stem:'Đội performance muốn dồn 100% ngân sách cho bản khuyến mãi. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý, vì CTR gấp đôi là bằng chứng rõ nhất để ra quyết định'},{k:'b',t:'Chia vai: bản kể chuyện xây nhận diện, bản khuyến mãi chốt đơn'},
             {k:'c',t:'Từ chối hẳn bản khuyến mãi vì nó không đúng hình ảnh thương hiệu'},{k:'d',t:'Chạy bản khuyến mãi nhưng đổi logo sang màu khác để khách khỏi nhận ra'}],
    answer:'b', why:{a:'CTR chỉ đo một phần; dồn hết là đánh đổi định vị lấy click.',
      b:'Đúng. Mỗi bản làm đúng việc của nó, và bản khuyến mãi không thành gương mặt duy nhất.',
      c:'Bản khuyến mãi vẫn hữu ích ở cuối phễu; bỏ hẳn là phí.',
      d:'Giấu thương hiệu thì mất luôn phần ghi nhớ; không giải quyết gì.'} },
  { type:'calc', stem:'Ngân sách quý 200 triệu đồng, chia 70% cho quảng cáo kể chuyện. Phần còn lại cho bản khuyến mãi là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:60, tol:0.1, wrong:[[140,'SAI_TINH_TOAN'],[30,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Phần cho bản khuyến mãi = 100% − 70% = 30%.','200 × 0,3 = <b>60 triệu đồng</b>.'] },
  { type:'mcq', stem:'Làm sao biết một creative có làm lệch định vị không, khi chỉ số quảng cáo không cho biết?',
    options:[{k:'a',t:'Xem số bình luận khen trên bài quảng cáo sau khi chạy xong'},{k:'b',t:'Đợi báo cáo doanh số cuối năm rồi so sánh với năm trước'},
             {k:'c',t:'Hỏi đội sáng tạo xem họ có thấy bản đó hợp thương hiệu không'},{k:'d',t:'Khảo sát nhanh khách đã xem: họ nhớ thương hiệu với từ gì'}],
    answer:'d', why:{a:'Bình luận là một nhóm nhỏ và lệch, không đại diện trí nhớ chung.',
      b:'Doanh số cuối năm bị quá nhiều yếu tố chen vào để quy cho creative.',
      c:'Ý kiến nội bộ hữu ích nhưng không thay được điều khách thực sự nhớ.',
      d:'Đúng. Hỏi thẳng điều khách liên tưởng mới đo được dấu vết thương hiệu.'} },
  { type:'mcq', stem:'Một hãng xe máy điện định vị "an toàn cho gia đình" thử bản quảng cáo đua tốc độ, CTR cao nhất. Nên xử lý thế nào?',
    options:[{k:'a',t:'Ghi nhận bài học về sự chú ý, nhưng không dùng làm creative chính'},{k:'b',t:'Dùng làm creative chính vì chỉ số cho thấy khách thích tốc độ hơn an toàn'},
             {k:'c',t:'Đổi định vị sang "tốc độ" ngay vì dữ liệu đã chứng minh điều đó'},{k:'d',t:'Xoá kết quả thử vì nó không phù hợp với kế hoạch đã duyệt từ đầu'}],
    answer:'a', why:{a:'Đúng. Có thể học cách thu hút (nhịp nhanh, chuyển động) mà giữ đúng thông điệp an toàn.',
      b:'Click không phải bằng chứng khách mua vì tốc độ; nó làm lệch lời hứa với gia đình.',
      c:'Đổi định vị dựa trên một bản thử CTR là quá vội và bỏ qua nghiên cứu khách.',
      d:'Kết quả thử vẫn là dữ liệu quý; không nên xoá.'} },
  { type:'mcq', stem:'Vì sao bản kể chuyện có CTR thấp hơn vẫn đáng giữ ngân sách lớn?',
    options:[{k:'a',t:'Vì CTR thấp nghĩa là quảng cáo tiết kiệm tiền hơn cho thương hiệu'},{k:'b',t:'Vì nó xây ký ức đúng định vị, giúp các lần mua sau dễ hơn'},
             {k:'c',t:'Vì đội sáng tạo đã tốn nhiều công làm nên không nỡ bỏ đi'},{k:'d',t:'Vì nền tảng chỉ cho phép chạy video dài khi có ngân sách thật lớn'}],
    answer:'b', why:{a:'CTR thấp không tự làm rẻ; lý do giữ là giá trị ghi nhớ.',
      b:'Đúng. Hiệu quả thương hiệu tích luỹ chậm, không hiện hết trong click.',
      c:'Công sức đã bỏ ra không phải lý do để giữ ngân sách.',
      d:'Không có quy định như vậy.'} },
  { type:'mcq', stem:'Người thấy chủ yếu bản khuyến mãi nhớ thương hiệu là "hay giảm giá". Hệ quả nào có thể xảy ra?',
    options:[{k:'a',t:'Khách sẽ trung thành hơn vì quen mua được giá rẻ'},{k:'b',t:'Thương hiệu được coi là cao cấp hơn nhờ xuất hiện dày đặc'},
             {k:'c',t:'Khách chờ đợt giảm mới mua, bán giá gốc ngày càng khó'},{k:'d',t:'Chi phí quảng cáo giảm dần vì khách đã quá quen với thương hiệu'}],
    answer:'c', why:{a:'Trung thành với giá rẻ dễ chuyển sang hãng khác rẻ hơn.',
      b:'Giảm giá thường xuyên kéo cảm nhận về phía bình dân, không phải cao cấp.',
      c:'Đúng. Khách học được rằng đợi là có giá tốt.',
      d:'Chi phí không tự giảm; nhiều khi phải giảm sâu hơn mới kéo được đơn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tn03-08', skill:'insight', read:'6 phút', t:'Cả phòng thích bản A, khách lại chọn bản B?',
  situation:'Một chuỗi bánh mì que ở Hải Phòng có hai poster. Bản A thiết kế tinh tế, tông pastel, chữ nhỏ. Bản B màu vàng đậm, chữ to "Giòn rụm – 10 nghìn". Cả 12 người trong văn phòng bỏ phiếu cho A. Chủ chuỗi định in 500 bản A để treo khắp các điểm bán.',
  concept:{ name:'Thử với khách thật vs hỏi ý kiến nội bộ',
    body:'Người trong nhà biết quá rõ sản phẩm, xem creative trên màn hình lớn, và chọn theo gu thẩm mỹ. Khách thì lướt qua trong hai giây, trên điện thoại hay từ xa trên xe máy, với nhu cầu cụ thể. Vì vậy <b>ý kiến nội bộ</b> hữu ích để loại lỗi, kiểm tra thông điệp đúng sai, nhưng không thay được <b>hành vi của khách thật</b>. Khi có thể, hãy để khách "bỏ phiếu" bằng hành động: bấm, dừng lại, mua.' },
  example:'Chủ chuỗi treo A ở 3 điểm, B ở 3 điểm tương đương trong hai tuần. Điểm treo B bán trung bình 460 que mỗi ngày, điểm treo A 400 que. Nhìn từ xe máy cách 10 mét, bản A gần như không đọc được giá. Chủ chuỗi in B cho toàn hệ thống, giữ A cho fanpage nơi người xem nhìn gần.',
  takeaway:'Nội bộ giúp loại lỗi; khách thật mới cho biết bản nào làm được việc.',
  points:["Người trong nhà xem creative từ gần, không vội, và đã biết sản phẩm. Khách thì lướt qua trong hai giây ngoài đường, nên phiếu nội bộ đo gu, không đo hành động.","Treo hai bản ở các điểm tương đương, cùng thời gian, để khác biệt chỉ đến từ poster. Điểm tương đương về lượng khách qua lại là điều kiện để đọc kết quả.","Đo bằng hành vi cần thước gắn với việc mua, như số que bán mỗi ngày. Hỏi “thích bản nào” cho câu trả lời lịch sự, còn đếm que cho câu thật."],
  counter:"Giả sử cũng chuỗi bánh mì que, nhưng hai poster treo ở hai khu rất khác nhau: A gần trường đại học, B ở chợ. Khi đó số que chênh có thể đến từ khách, không phải từ poster. Dấu hiệu nhận ra: các điểm đó đã bán chênh nhau trước khi treo poster. Lúc này hãy ghép điểm tương đương hoặc đổi poster qua lại giữa các điểm rồi đo lại.",
  deeper:"Người làm nghề không coi ý kiến nội bộ là kẻ thù mà gán cho nó đúng việc: soi lỗi chính tả, giá sai, thông điệp lệch. Đánh đổi nằm ở tốc độ: thử với khách thật mất hai tuần, ý kiến nội bộ chỉ mất một buổi. Tín hiệu cần theo dõi là hành vi trong đúng bối cảnh dùng thật, ví dụ khoảng cách nhìn từ xe máy. Khái niệm kề cận là thử theo từng kênh, vì cùng một thiết kế có thể thắng ở fanpage mà thua ngoài đường. Phép kiểm tra trong tuần: đứng cách poster 10 mét và nhờ ba người lạ đọc giá to lên.",
  apply:'Nhớ lại lần gần nhất cả nhóm chọn creative bằng ý kiến. Nói trong 60 giây: bạn có thể để khách thật "bỏ phiếu" bằng hành động nào, rẻ và nhanh.',
  mistakes:['Tin rằng cả phòng đồng ý thì chắc chắn khách cũng thích.','Xem creative trên màn hình máy tính lớn thay vì trong đúng bối cảnh khách thấy.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 12/12 người trong văn phòng chọn A. Điều đó cho biết gì về khách?',
    options:[{k:'a',t:'Khách cũng sẽ thích A, vì 12 trên 12 người là đồng thuận rất cao'},{k:'b',t:'Khách sẽ thích B vì người trong nghề hay chọn ngược với khách'},
             {k:'c',t:'Rất ít: người trong nhà nhìn khác với cách khách lướt qua poster'},{k:'d',t:'A sẽ bán tốt ở các kênh, vì thiết kế đẹp thì bán được nhiều hơn'}],
    answer:'c', why:{a:'Đồng thuận trong một nhóm giống nhau không nói lên hành vi của nhóm khác.',
      b:'Không có quy luật chọn ngược như vậy; chỉ là nhóm này không đại diện.',
      c:'Đúng. Họ khác khách về kiến thức, bối cảnh và cách nhìn.',
      d:'Đẹp không đồng nghĩa với dễ đọc và thúc đẩy mua trong bối cảnh thật.'} },
  { type:'mcq', stem:'Chủ chuỗi sắp in 500 bản A. Bạn đề xuất gì?',
    options:[{k:'a',t:'Treo thử A và B ở các điểm tương đương hai tuần, so số que bán ra'},{k:'b',t:'In 500 bản A ngay vì cả phòng đã nhất trí, tránh mất thời gian'},
             {k:'c',t:'Mời thêm 12 người thân quen bỏ phiếu nữa cho chắc rồi mới in'},{k:'d',t:'Thuê agency lớn thiết kế bản C thật đẹp để thay cả hai bản hiện có'}],
    answer:'a', why:{a:'Đúng. Rẻ, nhanh, đo bằng hành vi mua thật.',
      b:'In 500 bản là quyết định tốn kém dựa trên một nhóm không đại diện.',
      c:'Người thân quen vẫn là ý kiến, và dễ chiều theo chủ.',
      d:'Thêm bản đẹp không trả lời câu hỏi khách phản ứng thế nào.'} },
  { type:'calc', stem:'Điểm treo B bán trung bình 460 que/ngày, điểm treo A 400 que/ngày. B cao hơn A bao nhiêu phần trăm?',
    unit:'%', ans:15, tol:0.1, wrong:[[13,'SAI_MAU_SO'],[60,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Chênh lệch = 460 − 400 = 60 que.','60 ÷ 400 = 0,15 = <b>15%</b>.'] },
  { type:'mcq', stem:'Vậy ý kiến nội bộ có ích ở đâu trong quy trình thử creative?',
    options:[{k:'a',t:'Chọn bản cuối cùng, vì người trong nhà hiểu thương hiệu nhất'},{k:'b',t:'Không có ích gì, nên bỏ hẳn bước xem nội bộ để tiết kiệm thời gian'},
             {k:'c',t:'Dự báo doanh số, vì họ biết rõ số liệu bán hàng của từng điểm'},{k:'d',t:'Loại lỗi rõ ràng: sai giá, sai thông tin, lệch thương hiệu'}],
    answer:'d', why:{a:'Hiểu thương hiệu không có nghĩa là đoán đúng phản ứng khách.',
      b:'Bỏ hẳn thì dễ để lọt lỗi cơ bản ra ngoài.',
      c:'Số liệu cũ không dự báo phản ứng với creative mới.',
      d:'Đúng. Nội bộ là bộ lọc lỗi, khách thật là bộ lọc hiệu quả.'} },
  { type:'mcq', stem:'Một startup gọi 10 khách hỏi "Anh/chị thích quảng cáo nào hơn?". Hạn chế lớn nhất là gì?',
    options:[{k:'a',t:'Mười người là quá nhiều, tốn thời gian mà không cần thiết'},{k:'b',t:'Khách được hỏi sẽ xem kỹ, khác hẳn với lúc lướt thật ngoài đời'},
             {k:'c',t:'Khách sẽ chọn bản rẻ tiền hơn để startup đỡ tốn chi phí'},{k:'d',t:'Gọi điện cho khách là vi phạm quyền riêng tư nên không được phép'}],
    answer:'b', why:{a:'Mười người là ít chứ không nhiều; nhưng vấn đề lớn hơn là cách hỏi.',
      b:'Đúng. Hỏi trực tiếp đặt khách vào tình huống không tự nhiên; câu trả lời khác hành vi thật.',
      c:'Không có lý do khách chọn theo chi phí sản xuất.',
      d:'Không nên khẳng định; gọi khách đồng ý tham gia là việc phổ biến.'} },
  { type:'mcq', stem:'Vì sao chủ chuỗi giữ bản A cho fanpage?',
    options:[{k:'a',t:'Người xem fanpage nhìn gần trên điện thoại, thiết kế tinh tế đọc được'},{k:'b',t:'Làm hài lòng nhân viên văn phòng vì họ đã chọn bản A từ đầu'},
             {k:'c',t:'Fanpage không quan trọng nên dùng bản nào cũng được như nhau'},{k:'d',t:'Đối thủ không biết poster nào đang thật sự bán tốt ngoài điểm bán'}],
    answer:'a', why:{a:'Đúng. Bối cảnh xem khác thì bản phù hợp có thể khác; vẫn nên theo dõi số liệu fanpage.',
      b:'Làm hài lòng nội bộ không phải lý do chọn creative.',
      c:'Fanpage vẫn quan trọng; chọn A vì hợp bối cảnh, không phải vì tuỳ.',
      d:'Không liên quan; đối thủ nhìn thấy cả hai bản.'} },
  { type:'mcq', stem:'Một hãng bột giặt có ngân sách rất ít. Cách để khách thật "bỏ phiếu" rẻ nhất là gì?',
    options:[{k:'a',t:'Thuê công ty nghiên cứu tổ chức phỏng vấn nhóm tập trung vài buổi'},{k:'b',t:'Đợi chiến dịch chạy xong cả năm rồi xem doanh số tổng để đánh giá'},
             {k:'c',t:'Chạy hai ảnh quảng cáo nhỏ song song vài ngày, so tỉ lệ bấm'},{k:'d',t:'Đăng hai bản lên nhóm nội bộ công ty để lấy phiếu bầu nhanh gọn'}],
    answer:'c', why:{a:'Phỏng vấn nhóm có giá trị nhưng tốn kém hơn nhiều.',
      b:'Quá chậm và không tách được creative khỏi các yếu tố khác.',
      c:'Đúng. Vài trăm nghìn đến vài triệu đồng đã có hành vi thật để so.',
      d:'Vẫn là ý kiến nội bộ.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tn03-09', skill:'measure', read:'7 phút', t:'5 triệu mỗi tháng thì thử mấy biến thể?',
  situation:'Một tiệm nail ở Đà Nẵng có 5 triệu đồng mỗi tháng cho quảng cáo Facebook. Chủ tiệm đọc được lời khuyên "hãy thử thật nhiều creative" nên làm 10 bản, mỗi bản 500.000 đồng. Sau một tháng, mỗi bản chỉ có 3–8 tin nhắn, và chủ tiệm không biết bản nào thật sự tốt.',
  concept:{ name:'Số biến thể hợp với ngân sách',
    body:'Mỗi biến thể cần đủ kết quả để phân biệt với may rủi. Một cách ước lượng thô: ước tính chi phí mỗi kết quả, chia ngân sách thử cho số kết quả cần ở mỗi bản, ra số bản tối đa. Với ngân sách nhỏ, <b>ít biến thể nhưng khác nhau rõ</b> tốt hơn nhiều biến thể na ná. Thử 2–3 hướng khác biệt lớn (ví dụ: ảnh kết quả, video quy trình, ưu đãi khách mới), chọn hướng thắng rồi mới tinh chỉnh chi tiết ở vòng sau.' },
  example:'Chi phí mỗi tin nhắn khoảng 50.000 đồng. Chủ tiệm muốn mỗi bản có ít nhất khoảng 30 tin nhắn để so sánh đỡ nhiễu. Mỗi bản cần 30 × 50.000 = 1,5 triệu. Với 5 triệu, dành 4,5 triệu cho thử, tối đa 3 bản. Tháng sau, tiệm chạy ba hướng: ảnh bộ móng hoàn thiện, video 15 giây quy trình làm, ảnh ưu đãi "khách mới giảm 20%". Bản ảnh hoàn thiện đạt 41 tin nhắn, hai bản kia 26 và 23. Theo quy tắc ở bài tn02-03, chênh 41 với 26 là 15 tin, vẫn trong dao động 2×√(41 + 26) ≈ 16 — ảnh hoàn thiện là ứng viên dẫn đầu, cần một vòng nữa để xác nhận. (Mốc 30 kết quả mỗi bản là mức thô cho thử nhỏ; muốn đọc chắc hơn thì cần nhiều hơn, như mốc 50 đơn ở bài tn01-05.)',
  takeaway:'Ngân sách nhỏ: ít biến thể, khác nhau rõ, mỗi bản đủ kết quả để so.',
  apply:'Lấy ngân sách thử tháng tới của bạn. Nói trong 60 giây: chi phí mỗi kết quả ước tính, số kết quả cần mỗi bản, và từ đó bạn thử được mấy bản.',
  mistakes:['Chạy 10 biến thể với ngân sách nhỏ, mỗi bản quá ít dữ liệu để kết luận.','Thử các bản chỉ khác nhau một chữ hay một màu nút khi chưa tìm được hướng lớn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với 5 triệu đồng, chạy 10 biến thể hay 3 biến thể thì học được nhiều hơn?',
    options:[{k:'a',t:'10 bản, vì thử càng nhiều thì càng có cơ hội tìm được bản thắng'},{k:'b',t:'Như nhau, vì tổng ngân sách không đổi nên tổng dữ liệu cũng bằng nhau'},
             {k:'c',t:'3 bản, vì mỗi bản có đủ kết quả để so sánh đỡ bị may rủi chi phối'},{k:'d',t:'1 bản, vì dồn hết tiền vào một bản thì thuật toán tối ưu nhanh'}],
    answer:'c', why:{a:'Nhiều bản mà mỗi bản vài kết quả thì "bản thắng" có thể chỉ là may.',
      b:'Tổng dữ liệu bằng nhau nhưng chia mỏng thì từng so sánh yếu đi.',
      c:'Đúng. Đủ dữ liệu mỗi bản mới phân biệt được thắng thật.',
      d:'Một bản thì không có gì để so, không học được hướng nào tốt hơn.'} },
  { type:'mcq', stem:'Tháng tới tiệm nail vẫn có 5 triệu. Bạn đề xuất kế hoạch thử nào?',
    options:[{k:'a',t:'10 bản như cũ nhưng chạy lâu hơn, kéo dài sang cả tháng tiếp theo'},{k:'b',t:'5 bản chỉ khác màu chữ, để tìm ra màu nào thu hút khách nhiều nhất'},
             {k:'c',t:'Dồn hết vào bản có nhiều tin nhắn nhất tháng trước và thôi không thử'},{k:'d',t:'3 hướng khác biệt rõ, mỗi bản khoảng 1,5 triệu, chọn hướng thắng'}],
    answer:'d', why:{a:'Kéo dài có thể giúp nhưng chậm, và vẫn thử nhiều bản na ná.',
      b:'Khác màu chữ là tinh chỉnh nhỏ, nên để sau khi đã tìm được hướng lớn.',
      c:'Bản đó thắng với 8 tin nhắn có thể chỉ là may.',
      d:'Đúng. Vừa ngân sách, mỗi bản đủ dữ liệu, học được hướng nào đáng đi.'} },
  { type:'calc', stem:'Chi phí mỗi tin nhắn khoảng 50.000 đồng, mỗi biến thể cần khoảng 30 tin nhắn. Ngân sách thử 4,5 triệu đồng thì chạy được tối đa bao nhiêu biến thể?',
    unit:'bản', ans:3, tol:0, wrong:[[90,'SAI_TINH_TOAN'],[9,'QUEN_TI_LE_CHUYEN_DOI']], errors:['SAI_TINH_TOAN','QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Mỗi bản cần 30 × 50.000 = 1.500.000 đồng.','4.500.000 ÷ 1.500.000 = <b>3 bản</b>.'] },
  { type:'mcq', stem:'Bản ảnh hoàn thiện đạt 41 tin nhắn, hai bản kia 26 và 23. Bước tiếp theo hợp lý nhất?',
    options:[{k:'a',t:'Giữ hướng ảnh hoàn thiện, vòng sau thử 2–3 biến thể nhỏ trong hướng đó'},{k:'b',t:'Quay lại thử 10 hướng mới khác hẳn để khỏi bỏ sót ý tưởng hay'},
             {k:'c',t:'Tắt cả ba vì chưa bản nào đạt 50 tin nhắn như mức mong muốn ban đầu'},{k:'d',t:'Chuyển hết sang video vì video thường hiệu quả hơn ảnh trên mạng'}],
    answer:'a', why:{a:'Đúng. Tìm hướng lớn trước, rồi tinh chỉnh bên trong hướng đang dẫn; vòng sau cũng là lần xác nhận, vì chênh 41 với 26 còn nằm trong dao động may rủi.',
      b:'Mở lại 10 hướng là quay về vấn đề cũ: chia quá mỏng.',
      c:'Mức mong muốn không phải lý do bỏ; ảnh hoàn thiện đang dẫn, đáng giữ để xác nhận ở vòng sau.',
      d:'Dữ liệu của chính tiệm cho thấy ngược lại.'} },
  { type:'mcq', stem:'Vì sao ba hướng nên "khác nhau rõ" thay vì na ná nhau?',
    options:[{k:'a',t:'Vì nền tảng sẽ gộp các quảng cáo giống nhau lại thành một bản chạy'},{k:'b',t:'Vì khác biệt lớn tạo chênh lệch kết quả lớn, dễ thấy với ít dữ liệu'},
             {k:'c',t:'Vì khách sẽ khó chịu nếu thấy nhiều quảng cáo trông giống nhau'},{k:'d',t:'Vì bản na ná nhau cho kết quả y hệt nhau nên không có ý nghĩa'}],
    answer:'b', why:{a:'Không nên khẳng định cơ chế đó; lý do chính là khả năng phân biệt kết quả.',
      b:'Đúng. Chênh lệch nhỏ cần rất nhiều dữ liệu mới thấy; ngân sách nhỏ không đủ.',
      c:'Có thể có, nhưng không phải lý do chính khi thiết kế thử.',
      d:'Bản na ná vẫn khác nhau chút ít; chỉ là khó đo với ít dữ liệu.'} },
  { type:'mcq', stem:'Một shop quần áo có 50 triệu/tháng, chi phí mỗi đơn khoảng 100.000 đồng. So với tiệm nail, shop này có thể làm gì?',
    options:[{k:'a',t:'Vẫn chỉ nên thử 3 bản, vì đó là con số chuẩn trong sách'},{k:'b',t:'Không cần thử nữa, vì ngân sách lớn đã tự đảm bảo hiệu quả cao'},
             {k:'c',t:'Thử nhiều biến thể hơn, vì mỗi bản vẫn đủ dữ liệu để so sánh'},{k:'d',t:'Chạy 50 bản, mỗi bản 1 triệu, để tìm bản thắng nhanh nhất có thể'}],
    answer:'c', why:{a:'Số bản phụ thuộc ngân sách và chi phí mỗi kết quả, không cố định.',
      b:'Ngân sách lớn mà creative yếu vẫn phí tiền.',
      c:'Đúng. Cùng cách tính, ngân sách lớn hơn cho phép nhiều ô hơn.',
      d:'1 triệu chỉ ra khoảng 10 đơn mỗi bản; lại chia quá mỏng.'} },
  { type:'mcq', stem:'Bản ưu đãi "khách mới giảm 20%" có ít tin nhắn nhất. Có nên kết luận ưu đãi vô ích?',
    options:[{k:'a',t:'Có, vì dữ liệu đã cho thấy khách không quan tâm tới chuyện giảm giá'},{k:'b',t:'Có, và nên bỏ chương trình giảm 20% tại tiệm cho khách mới'},
             {k:'c',t:'Không, vì giảm giá hiệu quả hơn các hình thức quảng cáo khác'},{k:'d',t:'Chưa hẳn; chỉ biết ảnh ưu đãi kém thu hút hơn ảnh kết quả trong lần thử'}],
    answer:'d', why:{a:'Thử này so cách trình bày creative, không đo trực tiếp mức quan tâm tới giảm giá.',
      b:'Bỏ chương trình tại tiệm là quyết định khác, cần dữ liệu khác.',
      c:'Không có cơ sở cho nhận định đó; dữ liệu lần này cho kết quả ngược lại.',
      d:'Đúng. Kết luận nằm trong phạm vi thứ được thử.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:tn03-10', skill:'creative', read:'6 phút', t:'Thử xong rồi quên: làm sao để lần sau không thử lại từ đầu?',
  situation:'Một thương hiệu cà phê hoà tan đã chạy hơn 60 creative trong năm. Nhân viên cũ nghỉ, người mới hỏi "hook nào từng chạy tốt?", không ai trả lời được. Các file nằm rải rác trong nhiều thư mục, báo cáo mỗi lần một kiểu, và đội đang chuẩn bị thử lại một ý tưởng đã thua cách đây sáu tháng.',
  concept:{ name:'Thư viện bài học creative',
    body:'Mỗi lần thử là một bài học; nếu không ghi lại, bạn trả tiền hai lần cho cùng một bài học. <b>Thư viện creative</b> là một bảng đơn giản: mỗi dòng một lần so sánh, ghi ngày chạy, tệp khách, yếu tố được thử, so với bản nào, số hiển thị, chỉ số chính, kết quả, <b>độ tin cậy</b> (chênh lệch có vượt dao động may rủi không) và câu "vì sao chúng tôi nghĩ". Câu đó chỉ là <b>giả thuyết</b> cho đến khi lặp lại ở những lần thử độc lập. Điều quý nhất không phải file thiết kế mà là câu rút ra dùng được cho lần sau.' },
  example:'Đội tạo bảng tính chung với một dòng mẫu: "3/5 | nữ 25–35 | hook | cảnh rót cà phê so với chữ to | 20.000 hiển thị mỗi bản | CTR 1,9% so với 1,2% | thắng, chênh 140 lượt, vượt dao động ±50 | giả thuyết: hành động thật làm người xem dừng lại" (số minh hoạ). Ba tháng sau có 24 dòng. Lọc theo cột yếu tố, họ thấy 5 lần thử hook, cảnh rót thắng 4 lần nhưng chỉ 2 lần chênh vượt dao động. Ghi chú vì thế là "giả thuyết, cần thử thêm", chưa phải quy luật. Người mới đọc bảng trong 20 phút là biết điểm xuất phát; ý tưởng từng thua được đánh dấu, thử lại phải có lý do mới.',
  takeaway:'Ghi mỗi lần thử thành một dòng có câu "vì sao"; thư viện là thứ biến chi phí thử thành tài sản.',
  apply:'Mở lại lần thử creative gần nhất của bạn. Nói trong 60 giây: bạn sẽ ghi dòng thư viện cho nó thế nào, đặc biệt câu "vì sao".',
  mistakes:['Chỉ lưu file thiết kế và số liệu thô, không ghi câu rút ra.','Mỗi người ghi một kiểu nên không lọc hay so sánh được qua thời gian.','Rút "quy luật" từ vài lần thử chưa đủ chênh lệch, rồi áp cho mọi creative sau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong thư viện creative, thông tin nào có giá trị lâu dài nhất?',
    options:[{k:'a',t:'File thiết kế gốc với độ phân giải cao nhất để tái sử dụng về sau'},{k:'b',t:'Tên người làm ra creative để biết ai giỏi nhất trong đội sáng tạo'},
             {k:'c',t:'Tổng chi phí từng bản, để biết bản nào tốn tiền nhất trong năm'},{k:'d',t:'Câu rút ra "vì sao thắng/thua" có thể áp dụng cho lần sau'}],
    answer:'d', why:{a:'File hữu ích để tái dùng, nhưng không cho biết nên làm gì tiếp.',
      b:'Ghi tên người làm có ích cho quản lý, không phải bài học creative.',
      c:'Chi phí là dữ liệu cần, nhưng tự nó không thành bài học.',
      d:'Đúng. Câu rút ra mới là thứ dùng được khi làm creative mới.'} },
  { type:'mcq', stem:'Đội sắp thử lại ý tưởng đã thua sáu tháng trước. Bạn làm gì?',
    options:[{k:'a',t:'Cứ thử lại vì thị trường có thể đã thay đổi trong sáu tháng qua'},{k:'b',t:'Tìm lại kết quả cũ; chỉ thử lại nếu có lý do mới rõ ràng'},
             {k:'c',t:'Bỏ ý tưởng đó vì đã thua một lần thì thử lại cũng thua'},{k:'d',t:'Hỏi ý kiến cả đội xem có nên thử lại không rồi bỏ phiếu'}],
    answer:'b', why:{a:'Thị trường có thể đổi, nhưng phải nêu được điều gì đã đổi thì thử lại mới đáng.',
      b:'Đúng. Dựa trên bài học cũ, chỉ chi tiền khi có giả thuyết mới.',
      c:'Kết quả có điều kiện; bối cảnh khác có thể cho kết quả khác.',
      d:'Bỏ phiếu không thay được việc đọc lại dữ liệu đã có.'} },
  { type:'calc', stem:'Một dòng thư viện: mỗi bản 20.000 hiển thị, "cảnh rót" 380 lượt bấm (CTR 1,9%), "chữ to" 240 lượt (1,2%). Theo quy tắc ±2×√(kA + kB), dao động may rủi của chênh lệch là bao nhiêu lượt bấm (làm tròn 1 chữ số thập phân)?',
    unit:'lượt bấm', ans:49.8, tol:0.3, wrong:[[24.9,'SAI_TINH_TOAN'],[140,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN'],
    steps:['Tổng lượt bấm = 380 + 240 = 620.','√620 ≈ 24,9; nhân 2 ra ≈ <b>49,8 lượt</b>.','Chênh thực tế 140 lượt gấp gần 3 lần mức này nên dòng "thắng" đáng tin; cột độ tin cậy ghi được là "vượt dao động".'] },
  { type:'mcq', stem:'Cột nào giúp lọc bài học theo loại qua nhiều lần thử?',
    options:[{k:'a',t:'"Yếu tố được thử": hook, ảnh chính, thông điệp, lời kêu gọi'},{k:'b',t:'"Màu chủ đạo của creative" để thống kê màu nào được dùng nhiều nhất'},
             {k:'c',t:'"Người duyệt" để biết ai đã đồng ý cho bản đó chạy trước đó'},{k:'d',t:'"Tên file" để tìm nhanh bản thiết kế gốc trong thư mục chung'}],
    answer:'a', why:{a:'Đúng. Lọc theo yếu tố cho thấy khuôn mẫu, ví dụ loại hook nào thắng nhiều.',
      b:'Màu có thể là một yếu tố thử, nhưng không phải cột phân loại chung.',
      c:'Hữu ích cho quy trình, không giúp rút bài học.',
      d:'Cần để tìm file, nhưng không phân loại được bài học.'} },
  { type:'mcq', stem:'Một dòng ghi: "Bản B thắng, CTR 1,9%". Thiếu điều gì quan trọng nhất?',
    options:[{k:'a',t:'Thiếu tên agency đã làm bản B để lần sau thuê lại đúng người'},{k:'b',t:'Thiếu ảnh chụp màn hình bình luận của khách trên bài quảng cáo'},
             {k:'c',t:'Thiếu so với bản nào, thử yếu tố gì, và giả thuyết vì sao thắng'},{k:'d',t:'Thiếu định dạng số liệu thống nhất theo mẫu của phòng tài chính'}],
    answer:'c', why:{a:'Agency là thông tin phụ.',
      b:'Bình luận có thể bổ sung nhưng không phải cốt lõi.',
      c:'Đúng. Không có mốc so và câu "vì sao", con số không thành bài học.',
      d:'Định dạng thống nhất tốt, nhưng thiếu nội dung thì vẫn vô dụng.'} },
  { type:'mcq', stem:'Một quán bún chả nhỏ chỉ thử 1–2 creative mỗi tháng. Thư viện có cần thiết không?',
    options:[{k:'a',t:'Không, vì thư viện chỉ dành cho thương hiệu lớn thử hàng chục bản'},{k:'b',t:'Có, một bảng đơn giản vài cột; sau một năm đã có hơn chục bài học'},
             {k:'c',t:'Không, vì chủ quán tự nhớ được các lần thử mà không cần ghi'},{k:'d',t:'Có, nhưng phải mua phần mềm quản lý chuyên dụng mới làm đúng được'}],
    answer:'b', why:{a:'Chính người thử ít càng cần nhớ kỹ mỗi bài học đắt giá.',
      b:'Đúng. Chi phí ghi gần như bằng không, giá trị tích luỹ theo thời gian.',
      c:'Trí nhớ phai và lệch; sau vài tháng khó nhớ chính xác kết quả.',
      d:'Một bảng tính là đủ; không cần công cụ đắt.'} },
  { type:'mcq', stem:'Thư viện có 5 dòng thử hook: cảnh rót thắng 4 lần, nhưng chỉ 2 lần chênh vượt dao động, 3 lần gần như hoà. Câu rút ra nào nên ghi?',
    options:[{k:'a',t:'Giả thuyết: cảnh rót thắng chữ to với tệp nữ 25–35, mới có 2/5 lần đáng tin'},{k:'b',t:'Cảnh rót luôn thắng chữ to, áp dụng cho các creative cà phê sau này'},
             {k:'c',t:'Hook không quan trọng vì 3 lần gần như hoà, nên bỏ cột hook đi'},{k:'d',t:'Thắng 4/5 là 80%, đủ để coi là quy luật đã được kiểm chứng'}],
    answer:'a', why:{a:'Đúng. Chỉ 2 lần có bằng chứng đủ mạnh, phạm vi (tệp nữ 25–35) rõ, và đánh dấu giả thuyết để thử lại.',
      b:'"Luôn" vượt xa bằng chứng; mới 5 lần, 3 lần chưa phân biệt được với may rủi.',
      c:'Hoà nghĩa là chưa phân biệt được, không phải yếu tố vô nghĩa; có thể cần thử mạnh tay hơn.',
      d:'Tỉ lệ thắng đếm cả những lần chênh lệch nằm trong dao động; 4/5 trên mẫu nhỏ chưa phải quy luật.'} }
  ] }

] });
